// ═════════════════════════════════════

// ═══════════════════════════════════════════════════════════════════
// r62.3: Reusable production loading state for long-running scans
// ═══════════════════════════════════════════════════════════════════
// Replaces static "Loading..." text. Provides:
//   - Spinner (CSS animation:spin)
//   - Elapsed time counter (live ticker)
//   - Estimated total time (configurable per loader)
//   - Progress bar (indeterminate, pulses)
//   - Status line that can be updated mid-scan
//   - Cancel/abort button
//   - 90s timeout safety net (if API hangs, user gets an actionable error)
//
// Usage:
//   var loader = _csLoader({
//     title: "Intraday & Swing Setups",
//     subtitle: "Scanning S&P 100 · ALL TIMEFRAMES",
//     statusInitial: "Pulling 5-min bars for liquid names...",
//     estimatedSec: 45,                 // ~time first scan typically takes
//     onAbort: function(){ ... },       // optional abort callback
//   });
//   el.innerHTML = loader.html;
//   loader.start(el);                   // begin live ticker
//
//   // mid-scan, update status:
//   loader.setStatus("Now running detectors...");
//
//   // when done (success OR failure), call:
//   loader.stop();
//
window._csLoader = function(opts) {
  opts = opts || {};
  var id = "cs_loader_" + Math.random().toString(36).slice(2, 9);
  var startTs = 0;
  var tickerHandle = null;
  var aborted = false;

  var html = '' +
    '<div id="' + id + '" style="background:#fff;border:1px solid #e2e8f0;border-radius:8px;padding:30px;text-align:center;font-family:Inter,sans-serif">' +
      // spinner
      '<div style="display:inline-block;width:36px;height:36px;border:3px solid #1A3A78;border-top-color:transparent;border-radius:50%;animation:spin 0.8s linear infinite;margin-bottom:14px"></div>' +
      // title
      '<div style="font-size:14px;font-weight:700;color:#0f172a;margin-bottom:4px">' + (opts.title || "Loading") + '</div>' +
      // subtitle
      (opts.subtitle ? '<div style="font-size:10px;color:#64748b;font-family:\'IBM Plex Mono\',monospace;letter-spacing:0.5px;margin-bottom:14px">' + opts.subtitle + '</div>' : '') +
      // progress bar (indeterminate)
      '<div style="height:4px;border-radius:2px;background:#f1f5f9;max-width:380px;margin:0 auto 14px;overflow:hidden">' +
        '<div id="' + id + '_bar" style="height:100%;width:30%;background:#1A3A78;border-radius:2px;animation:csLoaderPulse 1.6s ease-in-out infinite"></div>' +
      '</div>' +
      // status line (mutable)
      '<div id="' + id + '_status" style="font-size:11px;color:#475569;line-height:1.5;font-family:Inter,sans-serif;max-width:480px;margin:0 auto 12px">' +
        (opts.statusInitial || "Working...") +
      '</div>' +
      // elapsed/estimated
      '<div style="display:flex;justify-content:center;gap:14px;font-size:10px;color:#94a3b8;font-family:\'IBM Plex Mono\',monospace;letter-spacing:0.4px;margin-bottom:14px">' +
        '<span>ELAPSED: <span id="' + id + '_elapsed" style="color:#1A3A78;font-weight:700">0s</span></span>' +
        (opts.estimatedSec ? '<span>~ ' + opts.estimatedSec + 's TYPICAL</span>' : '') +
      '</div>' +
      // abort button
      '<button id="' + id + '_abort" style="padding:5px 14px;border:1px solid #cbd5e1;background:#fff;color:#475569;border-radius:5px;font-size:10px;font-weight:700;cursor:pointer;font-family:Inter,sans-serif;letter-spacing:0.5px">CANCEL</button>' +
    '</div>' +
    '<style>' +
      '@keyframes spin { to { transform: rotate(360deg); } }' +
      '@keyframes csLoaderPulse { 0%,100% { width:25%; transform: translateX(0); } 50% { width:60%; transform: translateX(50%); } }' +
    '</style>';

  function start(rootEl) {
    startTs = Date.now();
    var elapsedEl = document.getElementById(id + "_elapsed");
    var abortBtn = document.getElementById(id + "_abort");

    // Live elapsed-time ticker
    tickerHandle = setInterval(function() {
      if (!elapsedEl) return;
      var sec = Math.floor((Date.now() - startTs) / 1000);
      elapsedEl.textContent = sec + "s";
      // Visual escalation if scan is taking longer than expected
      if (opts.estimatedSec && sec > opts.estimatedSec * 1.5) {
        elapsedEl.style.color = "#d97706";  // amber
      }
      if (opts.estimatedSec && sec > opts.estimatedSec * 2.5) {
        elapsedEl.style.color = "#dc2626";  // red
        // Update status to warn
        var statusEl = document.getElementById(id + "_status");
        if (statusEl && !aborted) {
          statusEl.innerHTML = '<span style="color:#d97706">⏱ Taking longer than usual — Yahoo may be rate-limiting. Wait or cancel.</span>';
        }
      }
    }, 500);

    // Wire abort button
    if (abortBtn) {
      abortBtn.onclick = function() {
        aborted = true;
        stop();
        if (typeof opts.onAbort === "function") {
          opts.onAbort();
        }
        if (rootEl) {
          rootEl.innerHTML = '<div style="background:#fff;border:1px solid #e2e8f0;border-radius:8px;padding:30px;text-align:center;color:#64748b;font-size:12px;font-family:Inter,sans-serif">Scan cancelled.</div>';
        }
      };
    }
  }

  function setStatus(text) {
    var s = document.getElementById(id + "_status");
    if (s) s.textContent = text;
  }

  function stop() {
    if (tickerHandle) {
      clearInterval(tickerHandle);
      tickerHandle = null;
    }
  }

  function isAborted() {
    return aborted;
  }

  return { html: html, start: start, setStatus: setStatus, stop: stop, isAborted: isAborted, id: id };
};

// Helper: wrap fetch with timeout + abort
window._csFetchWithTimeout = function(url, opts, timeoutMs) {
  timeoutMs = timeoutMs || 90000;  // 90s default
  var controller = (typeof AbortController !== "undefined") ? new AbortController() : null;
  var timeoutId = setTimeout(function() {
    if (controller) controller.abort();
  }, timeoutMs);
  var fetchOpts = Object.assign({}, opts || {}, controller ? { signal: controller.signal } : {});
  return fetch(url, fetchOpts).finally(function() { clearTimeout(timeoutId); });
};


function _sparkSVG(pts,c,w,h){if(!pts||pts.length<2)return'';var id='sp'+Math.random().toString(36).substr(2,6);var mn=Math.min.apply(null,pts),mx=Math.max.apply(null,pts),r=mx-mn||1;var path='';for(var i=0;i<pts.length;i++){var x=Math.round(i/(pts.length-1)*w);var y=Math.round(h-((pts[i]-mn)/r)*(h-4)-2);path+=(i===0?'M':'L')+x+','+y}var svg='<svg width="'+w+'" height="'+h+'" viewBox="0 0 '+w+' '+h+'" style="display:block;overflow:visible"><defs><linearGradient id="'+id+'" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="'+c+'" stop-opacity=".2"/><stop offset="100%" stop-color="'+c+'" stop-opacity="0"/></linearGradient></defs>';svg+='<path d="'+path+' L'+w+','+h+' L0,'+h+' Z" fill="url(#'+id+')" opacity=".8"/>';svg+='<path d="'+path+'" fill="none" stroke="'+c+'" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"/>';var lx=Math.round(w),ly=Math.round(h-((pts[pts.length-1]-mn)/r)*(h-4)-2);svg+='<circle cx="'+lx+'" cy="'+ly+'" r="2.5" fill="'+c+'"/></svg>';return svg}
function _progressRing(val,max,c,label,sz){var r=36,circ=2*Math.PI*r,pct=Math.min(val/max,1),offset=circ*(1-pct);return'<div style="text-align:center"><svg width="'+sz+'" height="'+sz+'" viewBox="0 0 80 80"><circle cx="40" cy="40" r="'+r+'" fill="none" stroke="#E2E8F0" stroke-width="5"/><circle cx="40" cy="40" r="'+r+'" fill="none" stroke="'+c+'" stroke-width="5" stroke-linecap="round" stroke-dasharray="'+circ+'" stroke-dashoffset="'+offset+'" transform="rotate(-90 40 40)"/><text x="40" y="38" text-anchor="middle" font-size="18" font-weight="800" fill="'+c+'" font-family="JetBrains Mono,monospace">'+val+'</text><text x="40" y="52" text-anchor="middle" font-size="10" fill="#5E6F8E">'+label+'</text></svg></div>'}
function _bellCurve(p10,p50,p90,now,S){var w=400,h=128,pad=40;var mn=p10*.85,mx=p90*1.15,rng=mx-mn||1;function xPos(v){return pad+(v-mn)/rng*(w-2*pad)}var pts=[];for(var i=0;i<=100;i++){var x=mn+i/100*rng,mu=p50,sig=(p90-p10)/3.29;var y=Math.exp(-.5*Math.pow((x-mu)/sig,2));pts.push({x:xPos(x),y:h-20-y*90})}var pathD='M'+pts[0].x+','+pts[0].y;for(var i=1;i<pts.length;i++)pathD+=' L'+pts[i].x+','+pts[i].y;var fillD=pathD+' L'+pts[pts.length-1].x+','+(h-20)+' L'+pts[0].x+','+(h-20)+' Z';var id='bc'+Math.random().toString(36).substr(2,4);var svg='<div style="height:130px;border-radius:14px;overflow:hidden;background:linear-gradient(180deg,#F8FAFC,#fff);border:1px solid #E2E8F0;padding:8px 12px;margin:12px 0"><svg viewBox="0 0 '+w+' '+h+'" style="width:100%;height:100%"><defs><linearGradient id="'+id+'" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="#1A3A78" stop-opacity=".15"/><stop offset="100%" stop-color="#1A3A78" stop-opacity=".01"/></linearGradient></defs><path d="'+fillD+'" fill="url(#'+id+')"/><path d="'+pathD+'" fill="none" stroke="#1A3A78" stroke-width="2" opacity=".6"/>';function marker(val,label,col,dash){var x=xPos(val);svg+='<line x1="'+x+'" y1="10" x2="'+x+'" y2="'+(h-20)+'" stroke="'+col+'" stroke-width="1.5"'+(dash?' stroke-dasharray="4,3"':'')+'/><text x="'+x+'" y="8" text-anchor="middle" font-size="9" font-weight="700" fill="'+col+'" font-family="Outfit,sans-serif">'+label+'</text><text x="'+x+'" y="'+(h-6)+'" text-anchor="middle" font-size="10" font-weight="800" fill="'+col+'" font-family="JetBrains Mono,monospace">'+S+val.toLocaleString()+'</text>'}marker(p10,"P10","#DC2626",true);marker(p50,"P50","#1A3A78",false);marker(p90,"P90","#059669",true);if(now)marker(now,"NOW","#D97706",true);svg+='</svg></div>';return svg}
function _52weekBar(lo,hi,now,sl,tgt,S){if(!lo||!hi||lo>=hi)return'';var rng=hi-lo,pct=Math.round((now-lo)/rng*100);var slPct=sl?Math.round((sl-lo)/rng*100):0;var tgtPct=tgt?Math.round((tgt-lo)/rng*100):0;var h='<div style="background:#fff;border:1px solid #E2E8F0;border-radius:16px;padding:22px 26px;margin-bottom:14px"><div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:14px"><div style="font-size:13px;font-weight:800;color:#0A1628;font-family:Outfit,sans-serif">52-Week Position</div><div style="font-family:JetBrains Mono,monospace;font-size:20px;font-weight:800;color:#1A3A78">'+S+now.toLocaleString()+'</div></div><div style="position:relative;height:10px;background:linear-gradient(90deg,#EF4444,#F59E0B 40%,#10B981);border-radius:5px;margin:8px 0"><div style="position:absolute;top:50%;left:'+pct+'%;transform:translate(-50%,-50%);width:18px;height:18px;border-radius:50%;background:#fff;border:3px solid #1A3A78;box-shadow:0 2px 10px rgba(26,58,120,.3);z-index:2"></div>';if(slPct>0)h+='<div style="position:absolute;left:'+slPct+'%;top:-6px;bottom:-6px;width:1px;border-left:2px dashed rgba(239,68,68,.3)"></div>';if(tgtPct>0)h+='<div style="position:absolute;left:'+tgtPct+'%;top:-6px;bottom:-6px;width:1px;border-left:2px dashed rgba(16,185,129,.3)"></div>';h+='</div><div style="display:flex;justify-content:space-between;font-family:JetBrains Mono,monospace;font-size:10px;color:#5E6F8E"><span>'+S+lo.toLocaleString()+' <span style="color:#DC2626">Low</span></span><span>'+S+hi.toLocaleString()+' <span style="color:#059669">High</span></span></div></div>';return h}
function _insightAction(i,a){return'<div style="margin-top:16px;border-radius:14px;overflow:hidden;border:1px solid #E2E8F0;display:grid;grid-template-columns:1fr 1fr"><div style="padding:18px 22px;background:#F8FAFC;border-right:1px solid #F1F5F9"><div style="font-size:9px;font-weight:800;letter-spacing:1px;text-transform:uppercase;color:#1A3A78;margin-bottom:4px">\u{1F4D6} INSIGHT</div><div style="font-size:12px;line-height:1.7;color:#0F2145">'+i+'</div></div><div style="padding:18px 22px;background:linear-gradient(135deg,rgba(16,185,129,.02),rgba(16,185,129,.04))"><div style="font-size:9px;font-weight:800;letter-spacing:1px;text-transform:uppercase;color:#047857;margin-bottom:4px">\u{1F3AF} ACTION</div><div style="font-size:12px;line-height:1.7;color:#047857;font-weight:600">'+a+'</div></div></div>'}
function _metricBox(l,v,s,c1,c2,sp){var h='<div style="background:#fff;border:1px solid #E2E8F0;border-radius:14px;padding:16px 12px;text-align:center;position:relative;overflow:hidden"><div style="font-size:8px;color:#5E6F8E;font-weight:700;letter-spacing:1.2px;text-transform:uppercase;margin-bottom:8px">'+l+'</div><div style="font-family:JetBrains Mono,monospace;font-size:22px;font-weight:800;color:'+(c1||"#0A1628")+'">'+v+'</div>';if(sp&&sp.length>1)h+=_sparkSVG(sp,c2||c1||"#1A3A78",80,24);if(s)h+='<div style="font-size:10px;color:#5E6F8E;margin-top:6px">'+s+'</div>';h+='<div style="position:absolute;bottom:0;left:0;right:0;height:3px;background:'+(c1||"#1A3A78")+'"></div></div>';return h}

// ═══ GLOBAL ERROR CATCHER — Shows errors visibly ═══
window.onerror = function(msg, src, line, col, err) {
  console.error('GLOBAL ERROR:', msg, 'at line', line);
  var d = document.createElement('div');
  d.style.cssText = 'position:fixed;bottom:10px;left:10px;right:10px;z-index:99999;padding:10px;background:#dc2626;color:#fff;font-size:11px;border-radius:8px;font-family:monospace;max-height:100px;overflow:auto';
  d.innerHTML = '<strong>JS Error (line ' + line + '):</strong> ' + msg + '<br><button onclick="this.parentElement.remove()" style="margin-top:4px;padding:2px 8px;background:#fff;color:#dc2626;border:none;border-radius:4px;cursor:pointer;font-size:10px">Dismiss</button>';
  document.body.appendChild(d);
  return false;
};
// ═══ GLOBAL ERROR SAFETY NET ═══
window.addEventListener('unhandledrejection', function(e){
e.preventDefault();
console.warn('Unhandled promise rejection:', e.reason);
});

