// Wraps all innerHTML assignments to sanitize HTML content
function _collapsible(title, icon, content, open) {
  return '<details style="margin-bottom:10px;border-radius:12px;border:1px solid var(--border);overflow:hidden;background:var(--surface)"'+(open?' open':'')+'>'+
    '<summary style="padding:12px 16px;cursor:pointer;display:flex;align-items:center;gap:8px;font-size:11px;font-weight:800;color:var(--text);font-family:Sora,sans-serif;user-select:none">'+
    '<span style="font-size:14px">'+icon+'</span>'+
    '<span style="flex:1">'+title+'</span>'+
    '<span style="font-size:8px;color:var(--text3);transition:transform .2s">▼</span>'+
    '</summary><div style="padding:12px 16px;border-top:1px solid var(--border)">'+content+'</div></details>';
}

function _safeHTML(html){
if(typeof DOMPurify !== 'undefined'){
return DOMPurify.sanitize(html, {
ADD_TAGS: ['svg','circle','line','text','rect','path','polygon','marker','defs','canvas'],
ADD_ATTR: ['viewBox','cx','cy','r','fill','stroke','stroke-width','stroke-dasharray','stroke-dashoffset',
'stroke-linecap','d','x','y','x1','y1','x2','y2','transform','text-anchor','font-size','font-weight',
'font-family','marker-end','markerWidth','markerHeight','refX','refY','orient','points','rx','ry',
'opacity','onclick','onmouseover','onmouseout','onkeydown','onkeypress','data-tab','data-subtab',
'data-asub','data-tradeid','data-theme','onerror'],
ALLOW_UNKNOWN_PROTOCOLS: true,
});
}
return html;  // Fallback if DOMPurify not loaded
}
// Override element.innerHTML setter globally for key containers
var _origSetInnerHTML = Object.getOwnPropertyDescriptor(Element.prototype, 'innerHTML').set;
function safeSetHTML(el, html){
_origSetInnerHTML.call(el, _safeHTML(html));
}


