// ═══ FRONTEND API CACHE — Reduces Yahoo rate limit hits ═══
var _apiCache={};var _apiCacheTTL=180;// 3 minutes
function _cachedFetch(url,ttl){
var ck=url;var cached=_apiCache[ck];
if(cached&&(Date.now()-cached.ts)<(ttl||_apiCacheTTL)*1000){
console.log('Cache HIT:',ck.substring(0,60));
return Promise.resolve(cached.data);
}
return fetch(url).then(function(r){if(!r.ok)throw new Error('API '+r.status);return r.json()}).then(function(d){
// Only cache GOOD responses — skip if data quality is bad
var _dq=d.dataQuality||d.v1DataQuality||'HIGH';
var _isGood=d.success!==false&&_dq!=='LOW'&&_dq!=='NONE'&&d.decision!=='DATA INSUFFICIENT';
if(_isGood){
  _apiCache[ck]={data:d,ts:Date.now()};
  var keys=Object.keys(_apiCache);if(keys.length>50){delete _apiCache[keys[0]];}
}else{
  console.log('Cache SKIP (bad data):',ck.substring(0,60),'quality:',_dq);
}
return d;
});
}
