var _reportShowing2=document.getElementById('report')&&document.getElementById('report').classList.contains('show');
if(!_reportShowing2)return;

window._isDreamUser=!!show;
var dreamTab=document.getElementById('tabBtnDream');
if(dreamTab)dreamTab.style.display=show?'':'none';
// lata@ is now BOTH trades + dream user — Decide tab already gated by _applyPremiumGating
