      _ih+='<div><div style="font-size:8px;font-weight:800;color:#4a6fa5">RISK PROFILE</div><div style="font-size:14px;font-weight:900;color:'+rp.color+'">'+rp.level+'</div></div>';
      _ih+='<div style="display:flex;gap:10px">';
