h+='<strong style="color:#6366f1">💡 Reading:</strong> ';
var nifty_chg=(in_.nifty50||{}).change||0;var sp_chg=(us.sp500||{}).change||0;
if(nifty_chg>0&&sp_chg>0)h+='Both India and US markets are positive today — global risk-on sentiment. ';
else if(nifty_chg<0&&sp_chg<0)h+='Both markets declining — possible global risk-off event. Check VIX and bond yields for confirmation. ';
else if(nifty_chg>0&&sp_chg<0)h+='India outperforming US today — domestic factors or FII rotation into India. ';
else h+='US outperforming India — check FII flows and USD/INR for capital movement signals. ';
if(vp>20)h+='VIX above 20 signals elevated uncertainty — tighter stop losses recommended.';
else h+='VIX below 20 — normal conditions for position building.';
