var inMap={nifty_etf:'NIFTYBEES',bank_etf:'BANKBEES',it_etf:'ITBEES',pharma_etf:'PHARMABEES'};
Object.keys(inMap).forEach(function(k){h+=_rptCard(inMap[k],ind[k],'₹','','#d97706')});
h+='</div></div>';
h+='</div>';
// COMMODITIES
h+='<div style="margin-bottom:10px"><div style="font-family:Sora,sans-serif;font-size:11px;font-weight:800;color:var(--text);margin-bottom:8px">🛢️ Commodities & Crypto</div>';
h+='<div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(110px,1fr));gap:8px">';
var comMap={gold:'🥇 Gold',silver:'🥈 Silver',crude_wti:'🛢️ WTI Crude',crude_brent:'🛢️ Brent',natgas:'🔥 Nat Gas',bitcoin:'₿ Bitcoin'};
Object.keys(comMap).forEach(function(k){h+=_rptCard(comMap[k],com[k],'$','','#f59e0b')});
h+='</div></div>';
// SECTOR INSIGHT
h+='<div style="padding:10px 14px;border-radius:8px;background:rgba(99,102,241,.04);border-left:3px solid #6366f1;font-size:9px;color:var(--text2);line-height:1.7">';
h+='<strong style="color:#6366f1">💡 Sector Rotation:</strong> ';
var bestUS='',bestUSc=-999;
Object.keys(us).forEach(function(k){if(us[k]&&us[k].change>bestUSc){bestUSc=us[k].change;bestUS=k}});
if(bestUS)h+='Strongest US sector today: <strong style="color:#10b981">'+bestUS.toUpperCase()+' (+'+bestUSc.toFixed(2)+'%)</strong>. ';
var oilChg=(com.crude_wti||{}).change||0;
if(Math.abs(oilChg)>2)h+='Oil moved '+(oilChg>0?'up':'down')+' '+Math.abs(oilChg).toFixed(1)+'% — '+(oilChg>0?'energy stocks benefit, India importers hurt':'energy stocks fall, India benefits from lower import bill')+'.';
