// ═══ 1. DARK/LIGHT THEME TOGGLE ═══
(function initTheme(){
const saved='light'; localStorage.setItem('celesys-theme','light');
document.documentElement.setAttribute('data-theme',saved);
window._currentTheme=saved;
})();

function toggleTheme(){
return; // PREMIUM: forced light
const next=window._currentTheme==='dark'?'light':'dark';
document.documentElement.setAttribute('data-theme',next);
window._currentTheme=next;
localStorage.setItem('celesys-theme',next);
const btn=document.getElementById('themeToggleBtn');
if(btn)btn.innerHTML=next==='dark'?'&#127763; Dark':'&#9728; Light';
}

// ═══ 2. PDF EXPORT ═══
async function exportPDF(){
if(!window._isPdfUser)return;

// If on the investor-decide tab, use the dedicated print-based PDF export
// html2canvas-based export fails on complex investor-decide pages (blank pages, truncation)
if(window._lastInvestorData && document.getElementById('deResult') && document.getElementById('deResult').innerHTML.length > 500){
  _investorExportPDF();
  return;
}
const btn=document.getElementById('pdfExportBtn');
if(btn){btn.innerHTML='&#9203; Generating...';btn.disabled=true;}
try{
// html2pdf loaded statically via script tag
if(!window.html2pdf){
alert('PDF library still loading. Please wait a moment and try again.');
if(btn){btn.innerHTML='&#128196;';btn.disabled=false;}
return;
}

// Get ticker name from current report header
const ticker=(document.getElementById('tickerTag')?.textContent||'Report').trim();
const company=(document.getElementById('companyName')?.textContent||'').trim();
const filename=(ticker+'_'+(company||'Celesys')+'_Report').replace(/[^a-zA-Z0-9_]/g,'_')+'.pdf';

// Clone only VISIBLE sections to avoid rendering hidden tabs
const wrapper=document.createElement('div');
wrapper.style.cssText='padding:16px;font-family:DM Sans,sans-serif;max-width:800px';

// Add header
wrapper.innerHTML='<div style="text-align:center;margin-bottom:16px;padding-bottom:12px;border-bottom:2px solid #1a56db"><div style="font-size:22px;font-weight:800;color:#1a56db;font-family:Sora,sans-serif">'+ticker+' — '+(company||'Stock Analysis')+'</div><div style="font-size:11px;color:#666;margin-top:4px">Celesys AI Report · '+(document.getElementById('timestamp')?.textContent||new Date().toLocaleDateString())+'</div></div>';

// Gather visible .sc sections from current tab
const visible=document.querySelectorAll('#tabContentArea .sc[data-tab]');
let count=0;
visible.forEach(sc=>{
if(sc.offsetParent!==null&&sc.style.display!=='none'){
const clone=sc.cloneNode(true);
// Remove interactive elements
clone.querySelectorAll('button,input,canvas,details').forEach(e=>{
if(e.tagName==='CANVAS'){
try{const img=document.createElement('img');img.src=sc.querySelector('canvas')?.toDataURL('image/png')||'';img.style.cssText='width:100%;max-height:200px';e.replaceWith(img);}catch(ex){e.remove();}
}else if(e.tagName==='DETAILS'){e.setAttribute('open','');}
else{e.remove();}
});
wrapper.appendChild(clone);
count++;
}
});

if(count===0){throw new Error('No visible content. Switch to a tab with data first.');}

// Add footer
wrapper.innerHTML+='<div style="margin-top:20px;padding-top:10px;border-top:1px solid #ddd;text-align:center;font-size:9px;color:#999">Generated by Celesys AI · celesys.ai · For educational purposes only. Not financial advice.</div>';

document.body.appendChild(wrapper);

const opt={
margin:[8,6,8,6],
filename:filename,
image:{type:'jpeg',quality:0.85},
html2canvas:{scale:1.2,useCORS:true,logging:false,backgroundColor:'#ffffff'},
jsPDF:{unit:'mm',format:'a4',orientation:'portrait'},
pagebreak:{mode:['avoid-all','css','legacy']}
};

await html2pdf().set(opt).from(wrapper).save();
document.body.removeChild(wrapper);

}catch(e){
console.error('PDF error:',e);
alert('PDF generation failed: '+e.message+'\n\nTip: Use Ctrl+P and Save as PDF as an alternative.');
}finally{
if(btn){btn.innerHTML='&#128196;';btn.disabled=false;}
}
}

// ═══ 3. SHARE (WhatsApp, Email, Copy) ═══
function shareReport(method){
const ticker=(document.getElementById('tickerTag')?.textContent||'Stock').trim();
const company=(document.getElementById('companyName')?.textContent||'').trim();
const price=window._stockData?.current_price||'';
const curr=window._stockCurr||'$';
const url=window.location.href;
const text=`📊 *${ticker}${company?' — '+company:''}* ${price?curr+price:''}

🤖 AI Stock Analysis by Celesys AI
• Piotroski F-Score, DCF Valuation, Monte Carlo
• Options Greeks, Kelly Criterion, Moat Analysis
• Elite Decision Engine with 8-Step Scoring

🔗 Analyze any stock FREE: ${url}`;

if(method==='whatsapp'){
window.open('https://api.whatsapp.com/send?text='+encodeURIComponent(text),'_blank');
}else if(method==='email'){
window.open('mailto:?subject='+encodeURIComponent(ticker+' — AI Stock Analysis | Celesys AI')+'&body='+encodeURIComponent(text),'_blank');
}else if(method==='copy'){
navigator.clipboard.writeText(text).then(()=>{
const btn=document.getElementById('copyShareBtn');
if(btn){const orig=btn.innerHTML;btn.innerHTML='&#9989; Copied!';setTimeout(()=>btn.innerHTML=orig,2000);}
}).catch(()=>prompt('Copy this link:',text));
}else if(navigator.share){
navigator.share({title:ticker+' Analysis',text:text,url:url}).catch(()=>{});
}
}

// ═══ 4. COMPARE 2 STOCKS ═══
async function compareStocks(){
const t1=document.getElementById('cmp_stock1')?.value?.trim();
const t2=document.getElementById('cmp_stock2')?.value?.trim();
const el=document.getElementById('cmp_result');
if(!t1||!t2||!el){el.innerHTML='<div style="color:var(--red);font-size:11px">Enter both stock names.</div>';return;}
el.innerHTML='<div style="text-align:center;padding:30px;color:var(--text3)"><div style="font-size:24px;animation:spin 1s linear infinite">&#9203;</div><div style="margin-top:6px;font-size:10px">Fetching data for both stocks...</div></div>';

try{
const [r1,r2]=await Promise.all([
fetch('/api/stock-data?company='+encodeURIComponent(t1)).then(r=>r.json()),
fetch('/api/stock-data?company='+encodeURIComponent(t2)).then(r=>r.json())
]);
if(!r1.success||!r2.success){el.innerHTML='<div style="color:var(--red);font-size:11px">Could not fetch data. Check stock names.</div>';return;}
renderComparison(r1,r2,el);
}catch(e){el.innerHTML='<div style="color:var(--red);font-size:11px">Error: '+e.message+'</div>';}
}

function renderComparison(a,b,el){
const S=a.currency==='INR'?'&#8377;':'$';
const _f=(v)=>{if(v==='N/A'||v===null||v===undefined)return 'N/A';const n=parseFloat(v);if(isNaN(n))return String(v);return n.toLocaleString('en-IN',{maximumFractionDigits:2});};
const _w=(va,vb,higher)=>{
if(va==='N/A'||vb==='N/A')return ['var(--text3)','var(--text3)'];
const na=parseFloat(va),nb=parseFloat(vb);
if(isNaN(na)||isNaN(nb))return ['var(--text3)','var(--text3)'];
if(higher){return na>nb?['#10b981','#ef4444']:na<nb?['#ef4444','#10b981']:['#f59e0b','#f59e0b'];}
else{return na<nb?['#10b981','#ef4444']:na>nb?['#ef4444','#10b981']:['#f59e0b','#f59e0b'];}
};

const metrics=[
{label:'Price',a:_f(a.current_price),b:_f(b.current_price),unit:S,higher:null},
{label:'Market Cap',a:_f(a.market_cap),b:_f(b.market_cap),unit:S,higher:true},
{label:'P/E Ratio',a:_f(a.pe_ratio),b:_f(b.pe_ratio),higher:false},
{label:'P/B Ratio',a:_f(a.pb_ratio),b:_f(b.pb_ratio),higher:false},
{label:'ROE',a:_f(a.roe),b:_f(b.roe),unit:'%',higher:true},
{label:'Profit Margin',a:_f(a.profit_margin),b:_f(b.profit_margin),unit:'%',higher:true},
{label:'Revenue Growth',a:_f(a.revenue_growth),b:_f(b.revenue_growth),unit:'%',higher:true},
{label:'Debt/Equity',a:_f(a.debt_to_equity),b:_f(b.debt_to_equity),higher:false},
{label:'Beta',a:_f(a.beta),b:_f(b.beta),higher:false},
{label:'Dividend Yield',a:_f(a.dividend_yield),b:_f(b.dividend_yield),unit:'%',higher:true},
{label:'EPS (TTM)',a:_f(a.eps_ttm),b:_f(b.eps_ttm),unit:S,higher:true},
{label:'Free Cash Flow',a:_f(a.free_cash_flow),b:_f(b.free_cash_flow),unit:S,higher:true},
{label:'Current Ratio',a:_f(a.current_ratio),b:_f(b.current_ratio),higher:true},
{label:'52W High',a:_f(a.week52_high),b:_f(b.week52_high),unit:S,higher:null},
{label:'52W Low',a:_f(a.week52_low),b:_f(b.week52_low),unit:S,higher:null},
{label:'Operating Margin',a:_f(a.operating_margin),b:_f(b.operating_margin),unit:'%',higher:true},
{label:'PEG Ratio',a:_f(a.peg_ratio),b:_f(b.peg_ratio),higher:false},
];

let scoreA=0,scoreB=0;
metrics.forEach(m=>{
if(m.higher===null)return;
const na=parseFloat(String(m.a).replace(/[^0-9.-]/g,'')),nb=parseFloat(String(m.b).replace(/[^0-9.-]/g,''));
if(isNaN(na)||isNaN(nb))return;
if(m.higher){if(na>nb)scoreA++;else if(nb>na)scoreB++;}
else{if(na<nb)scoreA++;else if(nb<na)scoreB++;}
});
const winner=scoreA>scoreB?a.company_name:scoreB>scoreA?b.company_name:'Tie';
const winC=scoreA>scoreB?'#10b981':scoreB>scoreA?'#3b82f6':'#f59e0b';

let h=`<div style="padding:16px;border-radius:12px;background:#ffffff;text-align:center;margin-bottom:14px">
<div style="font-size:9px;letter-spacing:2px;color:#4a6fa5">HEAD-TO-HEAD COMPARISON</div>
<div style="font-size:18px;font-weight:800;color:#0A1628;margin:4px 0">${a.company_name} <span style="color:var(--text3);font-size:14px">vs</span> ${b.company_name}</div>
<div style="font-size:13px;font-weight:700;color:${winC}">Winner: ${winner} (${scoreA}-${scoreB})</div>
</div>`;

h+=`<div style="overflow-x:auto"><table style="width:100%;border-collapse:collapse;font-size:10px">
<tr style="background:rgba(59,130,246,.06)"><th style="padding:8px;text-align:left;color:var(--text3);border-bottom:1px solid var(--border)">Metric</th><th style="padding:8px;text-align:right;color:#3b82f6;border-bottom:1px solid var(--border)">${a.company_name}</th><th style="padding:8px;text-align:right;color:#8b5cf6;border-bottom:1px solid var(--border)">${b.company_name}</th><th style="padding:8px;text-align:center;color:var(--text3);border-bottom:1px solid var(--border)">Winner</th></tr>`;
metrics.forEach(m=>{
const colors=m.higher!==null?_w(m.a,m.b,m.higher):['var(--text)','var(--text)'];
const w=m.higher===null?'-':colors[0]==='#10b981'?a.company_name.split(' ')[0]:colors[1]==='#10b981'?b.company_name.split(' ')[0]:'Tie';
h+=`<tr><td style="padding:6px 8px;border-bottom:1px solid var(--border);color:var(--text2)">${m.label}</td><td style="padding:6px 8px;text-align:right;border-bottom:1px solid var(--border);color:${colors[0]};font-weight:700;font-family:var(--mono)">${m.unit||''}${m.a}</td><td style="padding:6px 8px;text-align:right;border-bottom:1px solid var(--border);color:${colors[1]};font-weight:700;font-family:var(--mono)">${m.unit||''}${m.b}</td><td style="padding:6px 8px;text-align:center;border-bottom:1px solid var(--border);font-size:9px;color:var(--text3)">${w}</td></tr>`;
});
h+='</table></div>';

h+=`<div style="padding:12px;border-radius:8px;background:rgba(139,92,246,.04);border-left:3px solid #8b5cf6;margin-top:12px">
<div style="font-size:10px;font-weight:700;color:#8b5cf6">&#128161; Comparison Insight:</div>
<div style="font-size:9px;color:var(--text2);margin-top:4px;line-height:1.8">
${winner!=='Tie'?'<strong>'+winner+'</strong> wins on '+Math.max(scoreA,scoreB)+' out of '+metrics.filter(m=>m.higher!==null).length+' comparable metrics. ':'Both stocks are evenly matched. '}
${scoreA>scoreB?a.company_name+' has better fundamentals overall. ':scoreB>scoreA?b.company_name+' has better fundamentals overall. ':'Consider sector trends and growth potential to break the tie. '}
Remember: no single comparison tells the whole story. Consider industry dynamics, management quality, and your investment timeline.
</div></div>`;
el.innerHTML=h;
}

// ═══ 5. RENDER INSIDER ACTIVITY ═══
// ═══ PERFORMANCE LEADERBOARD ═══
async function fetchPerformanceLeaderboard(){
const el=document.getElementById('perfLeaderboard');
if(!el)return;
try{
const r=await fetch('/api/performance-leaderboard');
const data=await r.json();
if(!data.success){el.innerHTML='<div style="text-align:center;color:var(--text3);font-size:11px">Performance data unavailable</div>';return}
renderPerfLeaderboard(el,data);
}catch(e){el.innerHTML='<div style="text-align:center;color:var(--text3);font-size:11px">Could not load performance data</div>';}
}

function renderPerfLeaderboard(el,data){
const C=(v)=>v>=0?'var(--green)':'var(--red)';
const F=(v)=>v!==null&&v!==undefined?(v>=0?'+':'')+v.toFixed(1)+'%':'N/A';

const rankTbl=(title,icon,best,worst)=>{
if(!best||!best.length)return '';
let t='<div style="margin-bottom:10px"><div style="font-size:11px;font-weight:700;color:var(--text);margin-bottom:4px">'+icon+' '+title+'</div>';
t+='<div style="display:grid;grid-template-columns:1fr 1fr;gap:6px">';
t+='<div style="border-radius:6px;border:1px solid rgba(14,178,78,.12);overflow:hidden"><div style="padding:5px 8px;background:rgba(14,178,78,.06);font-size:9px;font-weight:700;color:var(--green)">&#128293; Best</div>';
best.forEach((s,i)=>{t+='<div style="padding:3px 8px;font-size:10px;display:flex;justify-content:space-between;border-bottom:1px solid var(--border)"><span>'+s.name+'</span><span style="font-weight:700;color:var(--green);font-family:var(--mono)">'+F(s.return)+'</span></div>'});
t+='</div>';
t+='<div style="border-radius:6px;border:1px solid rgba(205,0,75,.12);overflow:hidden"><div style="padding:5px 8px;background:rgba(205,0,75,.06);font-size:9px;font-weight:700;color:var(--red)">&#128308; Worst</div>';
(worst||[]).forEach((s,i)=>{t+='<div style="padding:3px 8px;font-size:10px;display:flex;justify-content:space-between;border-bottom:1px solid var(--border)"><span>'+s.name+'</span><span style="font-weight:700;color:var(--red);font-family:var(--mono)">'+F(s.return)+'</span></div>'});
t+='</div></div></div>';
return t;
};

const barChart=(items,yearKey)=>{
let b='';
const sorted=[...items].sort((a,b)=>{
const av=yearKey==='ytd'?(a.ytd||0):(a.yearly[yearKey]||0);
const bv=yearKey==='ytd'?(b.ytd||0):(b.yearly[yearKey]||0);
return bv-av;
});
sorted.forEach(idx=>{
const v=yearKey==='ytd'?(idx.ytd||0):(idx.yearly[yearKey]||0);
const w=Math.min(100,Math.abs(v)*2);
b+='<div style="display:flex;align-items:center;gap:6px;margin-bottom:3px">';
b+='<div style="width:90px;font-size:9px;font-weight:600;color:var(--text);text-align:right;flex-shrink:0;overflow:hidden;white-space:nowrap;text-overflow:ellipsis">'+idx.name+'</div>';
b+='<div style="flex:1;height:16px;background:var(--bg3);border-radius:3px;overflow:hidden"><div style="width:'+w+'%;height:100%;background:'+C(v)+';border-radius:3px;opacity:.7"></div></div>';
b+='<div style="width:50px;font-size:10px;font-weight:700;color:'+C(v)+';font-family:var(--mono);text-align:right">'+F(v)+'</div></div>';
});
return b;
};

// ═══ BUILD COUNTRY SECTION ═══
const buildCountry=(country,flag,sym,label)=>{
if(!country)return '';
let h='';

// YTD
h+='<div style="padding:14px;border-radius:10px;background:linear-gradient(135deg,rgba(0,47,108,.02),rgba(6,182,212,.01));border:1px solid var(--border);margin-bottom:12px">';
h+='<div style="font-size:13px;font-weight:800;color:var(--text);margin-bottom:10px">'+flag+' '+label+' — YTD '+data.current_year+'</div>';

if(country.indices.length)h+='<div style="margin-bottom:10px"><div style="font-size:10px;font-weight:700;color:var(--text3);margin-bottom:4px">INDICES</div>'+barChart(country.indices,'ytd')+'</div>';
if(country.ytd){
h+=rankTbl('Top & Bottom ETFs YTD','&#128230;',country.ytd.etfs?.best,country.ytd.etfs?.worst);
h+=rankTbl('Top & Bottom Stocks YTD','&#128202;',country.ytd.stocks?.best,country.ytd.stocks?.worst);
}
h+='</div>';

// Yearly
h+='<div style="padding:14px;border-radius:10px;background:#f1f5f9;border:1px solid var(--border)">';
h+='<div style="font-size:13px;font-weight:800;color:var(--text);margin-bottom:8px">'+flag+' '+label+' — Year-by-Year (5Y)</div>';

const years=data.years||[];
const geoKey=label.includes('India')?'in':'us';
h+='<div style="display:flex;gap:4px;flex-wrap:wrap;margin-bottom:10px">';
years.forEach((yr,i)=>{
h+='<button class="stab'+(i===0?' active':'')+'" onclick="showYearPerf'+geoKey+'(this,\''+yr+'\')" style="padding:3px 12px;font-size:10px">'+yr+'</button>';
});
h+='</div>';

years.forEach((yr,i)=>{
const yrData=country.yearly[yr]||{};
h+='<div class="yr-panel-'+geoKey+'" data-yr="'+yr+'" style="'+(i>0?'display:none':'')+'">';
if(country.indices.length)h+='<div style="margin-bottom:8px"><div style="font-size:10px;font-weight:700;color:var(--text3);margin-bottom:4px">INDICES IN '+yr+'</div>'+barChart(country.indices,yr)+'</div>';
if(yrData.stocks)h+=rankTbl('Stocks in '+yr,'&#128202;',yrData.stocks.best,yrData.stocks.worst);
if(yrData.etfs)h+=rankTbl('ETFs in '+yr,'&#128230;',yrData.etfs.best,yrData.etfs.worst);
h+='</div>';
});
h+='</div>';

return h;
};

// ═══ RENDER WITH COUNTRY TABS ═══
let h='';
h+='<div style="display:flex;gap:8px;margin-bottom:14px">';
h+='<button class="stab active" onclick="switchPerfGeo(this,\'india\')" style="padding:6px 18px;font-size:11px">India</button>';
h+='<button class="stab" onclick="switchPerfGeo(this,\'usa\')" style="padding:6px 18px;font-size:11px">USA</button>';
h+='</div>';

h+='<div id="perfIndia">'+buildCountry(data.india,'IN','₹','India')+'</div>';
h+='<div id="perfUsa" style="display:none">'+buildCountry(data.usa,'US','$','USA')+'</div>';

el.innerHTML=h;
}

// Country + Year switchers
window.switchPerfGeo=function(btn,geo){
document.getElementById('perfIndia').style.display=geo==='india'?'':'none';
document.getElementById('perfUsa').style.display=geo==='usa'?'':'none';
btn.parentElement.querySelectorAll('.stab').forEach(b=>b.classList.remove('active'));
btn.classList.add('active');
};
window.showYearPerfin=function(btn,yr){
document.querySelectorAll('.yr-panel-in').forEach(p=>p.style.display='none');
var panel=document.querySelector('.yr-panel-in[data-yr="'+yr+'"]');
if(panel)panel.style.display='block';
btn.parentElement.querySelectorAll('.stab').forEach(b=>b.classList.remove('active'));
btn.classList.add('active');
};
window.showYearPerfus=function(btn,yr){
document.querySelectorAll('.yr-panel-us').forEach(p=>p.style.display='none');
var panel=document.querySelector('.yr-panel-us[data-yr="'+yr+'"]');
if(panel)panel.style.display='block';
btn.parentElement.querySelectorAll('.stab').forEach(b=>b.classList.remove('active'));
btn.classList.add('active');
};

function renderInsiderActivity(d){
const el=document.getElementById('insiderSection');
if(!el)return;
const trades=d.insider_trades||[];
const buys=d.insider_buys||0;
const sells=d.insider_sells||0;
const signal=d.insider_signal||'N/A';
const S=d.currency==='INR'?'&#8377;':'$';
const _f=(v)=>{if(!v||v==='N/A')return 'N/A';const n=parseFloat(v);if(isNaN(n))return String(v);const a=Math.abs(n);if(a>=1e7)return S+(a/1e7).toFixed(2)+'Cr';if(a>=1e5)return S+(a/1e5).toFixed(2)+'L';return S+a.toLocaleString('en-IN');};

if(!trades.length&&signal==='N/A'){
el.innerHTML='<div style="padding:14px;border-radius:8px;background:rgba(139,92,246,.04);border:1px solid rgba(139,92,246,.12);text-align:center"><div style="font-size:12px;font-weight:700;color:var(--purple);margin-bottom:4px">&#128100; Insider Activity</div><div style="font-size:11px;color:var(--text2)">No recent insider transactions found. This could mean insiders are holding steady — neither buying nor selling. Check SEC/NSE filings for latest updates.</div></div>';
el.style.display='block';return;}
el.style.display='block';

const sigC=signal==='BULLISH'?'#10b981':signal==='BEARISH'?'#ef4444':'#f59e0b';
const sigE=signal==='BULLISH'?'&#128994;':signal==='BEARISH'?'&#128308;':'&#128992;';

let h=`<div style="font-size:11px;font-weight:700;color:var(--text);margin-bottom:8px">&#128100; Insider Activity — Follow the Smart Money</div>`;

h+=`<div style="padding:12px;border-radius:10px;background:rgba(139,92,246,.04);border-left:4px solid #8b5cf6;margin-bottom:10px">
<div style="font-size:10px;color:var(--text2);line-height:1.7">&#128161; <strong>Why it matters:</strong> When a CEO buys their own company stock with their own money, it is the ultimate vote of confidence — like a chef eating at their own restaurant. If insiders are selling heavily, it may signal they know something the market does not yet.</div>
</div>`;

h+=`<div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(120px,1fr));gap:8px;margin-bottom:10px">
<div style="padding:10px;border-radius:8px;border:2px solid ${sigC};background:${sigC}08;text-align:center"><div style="font-size:8px;color:#2d4373">Signal</div><div style="font-size:14px;font-weight:800;color:${sigC}">${sigE} ${signal}</div></div>
<div style="padding:10px;border-radius:8px;border:1px solid var(--border);text-align:center"><div style="font-size:8px;color:#2d4373">Buys</div><div style="font-size:18px;font-weight:800;color:#10b981">${buys}</div></div>
<div style="padding:10px;border-radius:8px;border:1px solid var(--border);text-align:center"><div style="font-size:8px;color:#2d4373">Sells</div><div style="font-size:18px;font-weight:800;color:#ef4444">${sells}</div></div>
</div>`;

if(trades.length>0){
h+=`<div style="overflow-x:auto;margin-bottom:10px"><table style="width:100%;border-collapse:collapse;font-size:9px">
<tr style="background:rgba(139,92,246,.06)"><th style="padding:6px;text-align:left;color:var(--text3);border-bottom:1px solid var(--border)">Date</th><th style="padding:6px;text-align:left;color:var(--text3);border-bottom:1px solid var(--border)">Insider</th><th style="padding:6px;text-align:left;color:var(--text3);border-bottom:1px solid var(--border)">Type</th><th style="padding:6px;text-align:right;color:var(--text3);border-bottom:1px solid var(--border)">Shares</th><th style="padding:6px;text-align:right;color:var(--text3);border-bottom:1px solid var(--border)">Value</th></tr>`;
trades.slice(0,8).forEach(t=>{
const isBuy=String(t.type||'').toLowerCase().includes('buy')||String(t.type||'').toLowerCase().includes('purchase');
h+=`<tr><td style="padding:4px 6px;border-bottom:1px solid var(--border);color:var(--text2)">${t.date||'N/A'}</td><td style="padding:4px 6px;border-bottom:1px solid var(--border);color:var(--text)">${(t.name||'').substring(0,25)}</td><td style="padding:4px 6px;border-bottom:1px solid var(--border);color:${isBuy?'#10b981':'#ef4444'};font-weight:700">${t.type||'N/A'}</td><td style="padding:4px 6px;text-align:right;border-bottom:1px solid var(--border);font-family:var(--mono)">${(t.shares||0).toLocaleString()}</td><td style="padding:4px 6px;text-align:right;border-bottom:1px solid var(--border);font-family:var(--mono)">${_f(t.value)}</td></tr>`;
});
h+='</table></div>';
}
el.innerHTML=h;
}

// ═══ 6. RENDER EARNINGS COUNTDOWN ═══
function renderEarningsCountdown(d){
const el=document.getElementById('earningsSection');
if(!el)return;
const nextE=d.next_earnings;
if(!nextE||nextE==='N/A'){
el.innerHTML='<div style="padding:14px;border-radius:8px;background:rgba(245,158,11,.04);border:1px solid rgba(245,158,11,.12);text-align:center"><div style="font-size:12px;font-weight:700;color:var(--amber);margin-bottom:4px">&#128197; Next Earnings Date</div><div style="font-size:11px;color:var(--text2)">Earnings date not yet announced. Check the company\'s investor relations page for updates.</div></div>';
el.style.display='block';return;}
el.style.display='block';

const S=d.currency==='INR'?'&#8377;':'$';
const _f=(v)=>{if(!v||v==='N/A')return 'N/A';const n=parseFloat(v);return isNaN(n)?String(v):n.toLocaleString('en-IN',{maximumFractionDigits:2});};

let daysLeft='N/A';
try{
const ed=new Date(nextE);
const now=new Date();
const diff=Math.ceil((ed-now)/(1000*60*60*24));
daysLeft=diff>0?diff+' days':diff===0?'TODAY':'Passed';
}catch(e){}

const estLow=_f(d.earnings_est_low);
const estHigh=_f(d.earnings_est_high);
const estAvg=_f(d.earnings_est_avg);
const revEst=_f(d.revenue_est_avg);

let h=`<div style="font-size:11px;font-weight:700;color:var(--text);margin-bottom:8px">&#128197; Earnings Countdown — Never Get Blindsided</div>`;

h+=`<div style="padding:12px;border-radius:10px;background:rgba(245,158,11,.04);border-left:4px solid #f59e0b;margin-bottom:10px">
<div style="font-size:10px;color:var(--text2);line-height:1.7">&#128161; <strong>Why it matters:</strong> Stocks can move 5-20% on earnings day. Knowing the date and expectations lets you prepare — take profits before, buy the dip after, or simply avoid getting caught off-guard. Think of it like knowing when your exam results come out — you want to be ready.</div>
</div>`;

h+=`<div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(120px,1fr));gap:8px;margin-bottom:10px">
<div style="padding:12px;border-radius:8px;border:2px solid #f59e0b;background:rgba(245,158,11,.06);text-align:center"><div style="font-size:8px;color:#2d4373">Next Earnings</div><div style="font-size:12px;font-weight:800;color:#f59e0b">${nextE}</div><div style="font-size:10px;font-weight:700;color:${daysLeft==='TODAY'?'#ef4444':parseInt(daysLeft)<7?'#f59e0b':'var(--text2)'}">${daysLeft}</div></div>
<div style="padding:12px;border-radius:8px;border:1px solid var(--border);text-align:center"><div style="font-size:8px;color:#2d4373">EPS Estimate</div><div style="font-size:14px;font-weight:700;color:var(--cyan);font-family:var(--mono)">${S}${estAvg}</div><div style="font-size:8px;color:#2d4373">Range: ${S}${estLow} — ${S}${estHigh}</div></div>
<div style="padding:12px;border-radius:8px;border:1px solid var(--border);text-align:center"><div style="font-size:8px;color:#2d4373">Revenue Estimate</div><div style="font-size:14px;font-weight:700;color:#8b5cf6;font-family:var(--mono)">${S}${revEst}</div></div>
${d.last_earnings&&d.last_eps_reported?`<div style="padding:12px;border-radius:8px;border:2px solid ${parseFloat(d.last_eps_surprise||0)>0?'#059669':'#dc2626'};background:${parseFloat(d.last_eps_surprise||0)>0?'rgba(5,150,105,.06)':'rgba(220,38,38,.06)'};text-align:center"><div style="font-size:8px;color:#2d4373">Last Reported</div><div style="font-size:14px;font-weight:700;color:${parseFloat(d.last_eps_surprise||0)>0?'#059669':'#dc2626'};font-family:var(--mono)">${S}${parseFloat(d.last_eps_reported).toFixed(2)}</div><div style="font-size:8px;color:${parseFloat(d.last_eps_surprise||0)>0?'#059669':'#dc2626'};font-weight:700">${d.last_earnings} · ${parseFloat(d.last_eps_surprise||0)>0?'Beat':'Missed'} ${d.last_eps_surprise!=='N/A'?Math.abs(parseFloat(d.last_eps_surprise||0)).toFixed(1)+'%':''}</div></div>`:''}\
</div>`;

el.innerHTML=h;
}

