// Direction change tracking + sound alert
var _lastDirection={};
function _playAlert(type){
try{
var ctx=new(window.AudioContext||window.webkitAudioContext)();
var osc=ctx.createOscillator();var gain=ctx.createGain();
osc.connect(gain);gain.connect(ctx.destination);
if(type==='bull'){osc.frequency.value=880;gain.gain.value=0.15;} // High pitch = bullish
else if(type==='bear'){osc.frequency.value=440;gain.gain.value=0.15;} // Low pitch = bearish
else{osc.frequency.value=660;gain.gain.value=0.1;} // Medium = direction change
osc.type='sine';osc.start();gain.gain.exponentialRampToValueAtTime(0.001,ctx.currentTime+0.3);
osc.stop(ctx.currentTime+0.3);
// Second beep for emphasis
setTimeout(function(){
var o2=ctx.createOscillator();var g2=ctx.createGain();
o2.connect(g2);g2.connect(ctx.destination);
o2.frequency.value=type==='bull'?1100:type==='bear'?330:880;o2.type='sine';
g2.gain.value=0.12;o2.start();g2.gain.exponentialRampToValueAtTime(0.001,ctx.currentTime+0.25);o2.stop(ctx.currentTime+0.25);
},150);
}catch(e){}
}
