var _wB=0;if(_rsi2>60&&_trend2>=3)_wB=2;else if(_rsi2>50)_wB=1;else if(_rsi2<40)_wB=-2;else if(_rsi2<50)_wB=-1;
var _mB=0;if(_earnG>10&&_priceChg3m<0)_mB=2;else if(_earnG>5)_mB=1;else if(_earnG<-5)_mB=-1;
