var _v3R=[{s:'RSI',v:Math.round(_rsi2),c:_rsi2>60?'#10b981':_rsi2<40?'#ef4444':'#f59e0b'},{s:'Trend',v:_trend2+'/4',c:_trend2>=3?'#10b981':_trend2<=1?'#ef4444':'#f59e0b'},{s:'Fwd PE',v:_fwdPE.toFixed(1)+'x',c:_fwdPE>0&&_fwdPE<20?'#10b981':_fwdPE>35?'#ef4444':'#f59e0b'},{s:'Signals',v:_totalBull+'B/'+_totalBear+'R',c:_totalBull>_totalBear?'#10b981':'#ef4444'},{s:'Week',v:_wD,c:_wC2},{s:'Month',v:_mD,c:_mC2}];
