// ═══ MY POSITION ANALYZER — Personalized hold/average/exit advice ═══
// ═══ MY POSITION ANALYZER — Comprehensive investor ready reckoner ═══
function _analyzeMyPosition(sym,currentPrice,csym,levels,fScore,upside,moatScore,decision){
var entryEl=document.getElementById('myEntryPrice_'+sym);
var qtyEl=document.getElementById('myQty_'+sym);
var resultEl=document.getElementById('myPositionResult_'+sym);
if(!entryEl||!resultEl)return;
var entry=parseFloat(entryEl.value);
if(!entry||entry<=0){entryEl.style.borderColor='var(--red)';setTimeout(function(){entryEl.style.borderColor=''},2000);return}
var qty=parseInt(qtyEl&&qtyEl.value)||10;
var S=csym;var lv=typeof levels==='string'?JSON.parse(levels):levels;
var pnlPct=((currentPrice-entry)/entry*100);
var pnlAbs=(currentPrice-entry);
var isLoss=currentPrice<entry;
var totalInvested=entry*qty;
var currentValue=currentPrice*qty;
var unrealizedPnl=currentValue-totalInvested;
var recoveryNeeded=isLoss?((entry/currentPrice-1)*100):0;
var drawdown=isLoss?((1-currentPrice/entry)*100):0;
var c=isLoss?'#ef4444':'#10b981';
var fairValue=lv.fairValue||0;
var hi52=lv.hi52||0;var lo52=lv.lo52||0;
var h='';
// SECTION 1: POSITION DASHBOARD
h+='<div style="padding:16px;border-radius:14px;background:linear-gradient(135deg,'+c+'08,'+c+'03);border:2px solid '+c+'20;margin-bottom:12px">';
h+='<div style="font-size:10px;font-weight:900;color:var(--text3);letter-spacing:1px;margin-bottom:10px">YOUR POSITION DASHBOARD</div>';
h+='<div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(100px,1fr));gap:8px">';
h+='<div style="padding:10px;border-radius:10px;background:var(--surface);text-align:center"><div style="font-size:7px;color:#2d4373;font-weight:700">P&L</div><div style="font-size:20px;font-weight:900;color:'+c+';font-family:var(--mono)">'+(pnlPct>0?'+':'')+pnlPct.toFixed(1)+'%</div><div style="font-size:8px;color:'+c+'">'+(isLoss?'Loss':'Gain')+': '+S+Math.abs(pnlAbs).toFixed(0)+'/share</div></div>';
h+='<div style="padding:10px;border-radius:10px;background:var(--surface);text-align:center"><div style="font-size:7px;color:#2d4373;font-weight:700">INVESTED</div><div style="font-size:14px;font-weight:900;color:var(--text);font-family:var(--mono)">'+S+totalInvested.toLocaleString()+'</div><div style="font-size:8px;color:#2d4373">'+qty+' shares</div></div>';
h+='<div style="padding:10px;border-radius:10px;background:var(--surface);text-align:center"><div style="font-size:7px;color:#2d4373;font-weight:700">CURRENT VALUE</div><div style="font-size:14px;font-weight:900;color:'+c+';font-family:var(--mono)">'+S+currentValue.toLocaleString()+'</div><div style="font-size:8px;color:'+c+'">'+S+Math.abs(unrealizedPnl).toLocaleString()+' '+(isLoss?'loss':'gain')+'</div></div>';
if(isLoss){h+='<div style="padding:10px;border-radius:10px;background:var(--surface);text-align:center"><div style="font-size:7px;color:#2d4373;font-weight:700">TO BREAKEVEN</div><div style="font-size:14px;font-weight:900;color:#f59e0b;font-family:var(--mono)">+'+recoveryNeeded.toFixed(0)+'%</div><div style="font-size:8px;color:#2d4373">need '+S+entry.toLocaleString()+'</div></div>';}
h+='</div></div>';
// SECTION 2: RISK-REWARD MATRIX
h+='<div style="padding:14px;border-radius:14px;background:var(--surface);border:1px solid var(--border);margin-bottom:12px">';
h+='<div style="font-size:10px;font-weight:900;color:var(--text3);letter-spacing:1px;margin-bottom:10px">RISK-REWARD — YOUR 3 OPTIONS</div>';
var holdTarget=fairValue>0?fairValue:currentPrice*1.3;var holdUpside=((holdTarget-currentPrice)/currentPrice*100).toFixed(0);var holdGain=((holdTarget-entry)*qty).toFixed(0);
h+='<div style="padding:12px;border-radius:10px;background:#3b82f606;border:1px solid #3b82f615;margin-bottom:8px"><div style="display:flex;justify-content:space-between;align-items:center"><div><div style="font-size:11px;font-weight:900;color:#3b82f6">A: HOLD — Wait for Fair Value '+S+holdTarget.toLocaleString()+'</div><div style="font-size:9px;color:var(--text2);margin-top:3px;line-height:1.5">'+holdUpside+'% upside from here. '+(parseFloat(holdGain)>=0?'You would profit '+S+Math.abs(holdGain).toLocaleString()+'.':'Still a loss of '+S+Math.abs(holdGain).toLocaleString()+' at fair value.')+'</div></div><div style="font-size:16px;font-weight:900;color:#3b82f6;font-family:var(--mono);flex-shrink:0;margin-left:10px">'+holdUpside+'%</div></div></div>';
if(isLoss){var addQty=Math.max(1,Math.round(qty*0.5));var newAvg=((entry*qty+currentPrice*addQty)/(qty+addQty));var newRec=((newAvg/currentPrice-1)*100).toFixed(0);var addCost=currentPrice*addQty;
h+='<div style="padding:12px;border-radius:10px;background:#f59e0b06;border:1px solid #f59e0b15;margin-bottom:8px"><div style="display:flex;justify-content:space-between;align-items:center"><div><div style="font-size:11px;font-weight:900;color:#f59e0b">B: AVERAGE DOWN — Add '+addQty+' shares at '+S+currentPrice.toLocaleString()+'</div><div style="font-size:9px;color:var(--text2);margin-top:3px;line-height:1.5">New avg: '+S+newAvg.toFixed(0)+' (was '+S+entry.toLocaleString()+'). Cost: '+S+addCost.toLocaleString()+'. Breakeven: +'+recoveryNeeded.toFixed(0)+'% → +'+newRec+'%.'+(fScore>=6?' Quality supports this.':' ⚠️ F-Score '+fScore+'/9 — risky.')+'</div></div><div style="font-size:16px;font-weight:900;color:#f59e0b;font-family:var(--mono);flex-shrink:0;margin-left:10px">'+S+newAvg.toFixed(0)+'</div></div></div>';}
h+='<div style="padding:12px;border-radius:10px;background:#ef444406;border:1px solid #ef444415;margin-bottom:8px"><div style="display:flex;justify-content:space-between;align-items:center"><div><div style="font-size:11px;font-weight:900;color:#ef4444">C: EXIT — Sell at '+S+currentPrice.toLocaleString()+'</div><div style="font-size:9px;color:var(--text2);margin-top:3px;line-height:1.5">'+(isLoss?'Book loss '+S+Math.abs(unrealizedPnl).toLocaleString()+'. '+(S==='₹'?'Tax benefit: offset gains, save ~'+S+Math.round(Math.abs(unrealizedPnl)*0.15).toLocaleString()+' in tax. ':'Tax loss harvesting available. ')+'Free up '+S+currentValue.toLocaleString()+' for redeployment.':'Book profit '+S+unrealizedPnl.toLocaleString()+'. '+(S==='₹'?'Tax: ~'+S+Math.round(unrealizedPnl*0.125).toLocaleString()+' LTCG.':'Capital gains tax applies.'))+' </div></div><div style="font-size:16px;font-weight:900;color:#ef4444;font-family:var(--mono);flex-shrink:0;margin-left:10px">'+S+Math.abs(unrealizedPnl).toLocaleString()+'</div></div></div>';
h+='</div>';
// SECTION 3: RECOVERY TIMELINE (if in loss)
if(isLoss){
h+='<div style="padding:14px;border-radius:14px;background:var(--surface);border:1px solid var(--border);margin-bottom:12px">';
h+='<div style="font-size:10px;font-weight:900;color:var(--text3);letter-spacing:1px;margin-bottom:10px">RECOVERY TIMELINE</div>';
h+='<div style="display:grid;grid-template-columns:repeat(4,1fr);gap:6px;margin-bottom:10px">';
[10,15,20,30].forEach(function(cagr){var years=Math.ceil(Math.log(entry/currentPrice)/Math.log(1+cagr/100));var yC=years<=2?'#10b981':years<=4?'#f59e0b':'#ef4444';
h+='<div style="padding:10px;border-radius:10px;background:'+yC+'06;border:1px solid '+yC+'15;text-align:center"><div style="font-size:7px;color:#2d4373;font-weight:700">IF '+cagr+'% CAGR</div><div style="font-size:18px;font-weight:900;color:'+yC+';font-family:var(--mono)">'+years+'</div><div style="font-size:8px;color:#2d4373">years</div></div>';});
h+='</div>';
var yrs15=Math.ceil(Math.log(entry/currentPrice)/Math.log(1.15));
h+='<div style="padding:8px 14px;border-radius:8px;background:rgba(99,102,241,.04);border-left:3px solid #6366f1;font-size:9px;color:var(--text2);line-height:1.7"><strong style="color:#6366f1">💡 Reality check:</strong> At 15% CAGR (above average), it takes '+yrs15+' years just to break even. That\'s '+yrs15+' years of zero returns while your money could compound elsewhere at 12% in an index fund.</div>';
h+='</div>';}
// SECTION 4: OPPORTUNITY COST
h+='<div style="padding:14px;border-radius:14px;background:var(--surface);border:1px solid var(--border);margin-bottom:12px">';
h+='<div style="font-size:10px;font-weight:900;color:var(--text3);letter-spacing:1px;margin-bottom:10px">OPPORTUNITY COST — WHAT IF YOU SWITCH?</div>';
h+='<div style="font-size:10px;color:var(--text);line-height:1.7;margin-bottom:8px">If you sell now and put '+S+currentValue.toLocaleString()+' into an index fund:</div>';
h+='<div style="display:grid;grid-template-columns:repeat(3,1fr);gap:6px">';
[3,5,10].forEach(function(yr){var idxR=Math.round(currentValue*Math.pow(1.12,yr));var stkR=Math.round(currentValue*Math.pow(1+(fScore>=7?0.18:fScore>=5?0.12:0.06),yr));
h+='<div style="padding:10px;border-radius:10px;background:#f1f5f9;text-align:center"><div style="font-size:7px;color:#2d4373;font-weight:700">'+yr+' YEARS</div><div style="font-size:8px;color:#3b82f6;font-weight:700;margin-top:4px">Index: '+S+idxR.toLocaleString()+'</div><div style="font-size:8px;color:#1A3A78;font-weight:700;margin-top:2px">Stock: '+S+stkR.toLocaleString()+'</div><div style="font-size:7px;color:#2d4373;margin-top:2px">'+(stkR>idxR?'Stock wins':'Index wins')+'</div></div>';});
h+='</div></div>';
// SECTION 5: DCA PLAN (if loss + quality)
if(isLoss&&fScore>=5){
h+='<div style="padding:14px;border-radius:14px;background:var(--surface);border:1px solid var(--border);margin-bottom:12px">';
h+='<div style="font-size:10px;font-weight:900;color:var(--text3);letter-spacing:1px;margin-bottom:10px">SMART DCA PLAN — 4 TRANCHES</div>';
var t1=currentPrice;var t2=Math.round(currentPrice*0.92);var t3=Math.round(currentPrice*0.85);var t4=lv.fireSale||Math.round(currentPrice*0.78);
var addPer=Math.max(1,Math.round(qty*0.25));var rS=qty;var rC=totalInvested;
[{p:t1,l:'Now'},{p:t2,l:'-8%'},{p:t3,l:'-15%'},{p:t4,l:'Fire sale'}].forEach(function(dl,i){
rS+=addPer;rC+=dl.p*addPer;var nA=rC/rS;
h+='<div style="display:flex;align-items:center;gap:10px;padding:8px 0;border-bottom:1px solid var(--border)"><div style="width:22px;height:22px;border-radius:50%;background:'+['#3b82f6','#1A3A78','#059669','#d97706'][i]+'15;color:'+['#3b82f6','#1A3A78','#059669','#d97706'][i]+';display:flex;align-items:center;justify-content:center;font-size:10px;font-weight:900;flex-shrink:0">'+(i+1)+'</div><div style="flex:1"><div style="font-size:10px;font-weight:800;color:var(--text)">Buy '+addPer+' at '+S+dl.p.toLocaleString()+' ('+dl.l+')</div><div style="font-size:8px;color:#2d4373">Total: '+rS+' shares · Avg: '+S+nA.toFixed(0)+' · Breakeven: +'+((nA/dl.p-1)*100).toFixed(0)+'%</div></div></div>';});
h+='<div style="margin-top:8px;padding:8px 14px;border-radius:8px;background:#10b98108;border-left:3px solid #10b981;font-size:9px;color:var(--text2);line-height:1.5"><strong style="color:#10b981">After full DCA:</strong> '+rS+' shares at '+S+(rC/rS).toFixed(0)+' avg. Additional cost: '+S+(rC-totalInvested).toLocaleString()+'.</div>';
h+='</div>';}
// SECTION 6: FINAL CALL
var actionC,actionLabel,actionDetail;
if(isLoss&&drawdown>50&&fScore<=4){actionC='#ef4444';actionLabel='EXIT — Cut Losses';actionDetail='Deep loss + weak business. Book tax loss, redeploy into quality.';}
else if(isLoss&&drawdown>30&&fScore>=6&&upside>10){actionC='#f59e0b';actionLabel='AVERAGE DOWN — In Tranches';actionDetail='Strong business temporarily down. Use the DCA plan above. Don\'t deploy all at once.';}
else if(isLoss&&drawdown<=30&&fScore>=5){actionC='#3b82f6';actionLabel='HOLD + SMALL ADD';actionDetail='Moderate pullback in decent business. Add 20-30% more. Stop-loss at '+S+Math.round(currentPrice*0.85).toLocaleString()+'.';}
else if(isLoss&&fScore<=4){actionC='#ef4444';actionLabel='HOLD — DO NOT ADD';actionDetail='Weak fundamentals. Don\'t throw good money after bad. Review after next quarter.';}
else if(!isLoss&&pnlPct>50&&upside<0){actionC='#10b981';actionLabel='BOOK PARTIAL PROFIT';actionDetail='Excellent gains and now overvalued. Sell 30-50%, let rest ride with trailing stop.';}
else if(!isLoss&&upside>15){actionC='#10b981';actionLabel='HOLD — Room to Run';actionDetail='In profit and still undervalued. Let winners compound.';}
else{actionC='#3b82f6';actionLabel='HOLD — Monitor';actionDetail='No urgent action. Review after next quarterly results.';}
h+='<div style="padding:16px;border-radius:14px;background:linear-gradient(135deg,'+actionC+'10,'+actionC+'04);border:2px solid '+actionC+'30"><div style="display:flex;align-items:center;gap:12px"><div style="font-size:28px">'+(actionLabel.indexOf('EXIT')>=0?'\uD83D\uDEAA':actionLabel.indexOf('AVERAGE')>=0?'\uD83D\uDCC9':actionLabel.indexOf('PROFIT')>=0?'\uD83D\uDCB0':'\uD83D\uDCCC')+'</div><div><div style="font-size:14px;font-weight:900;color:'+actionC+';font-family:Sora,sans-serif">'+actionLabel+'</div><div style="font-size:11px;color:var(--text);margin-top:4px;line-height:1.7">'+actionDetail+'</div></div></div></div>';
resultEl.innerHTML=h;
}

