window._lastInvestorData.sma_50=d.sma50||d.sma_50||(d.technicals?d.technicals.sma50:0)||0;
window._lastInvestorData.sma_200=d.sma200||(d.technicals?d.technicals.sma200:0)||0;
window._lastInvestorData.rsi=d.rsi||(d.technicals?d.technicals.rsi:0)||0;
window._lastInvestorData.debt_to_equity=d.debtEquity||0;
window._lastInvestorData.fairValue=d.levels?d.levels.fairValue:0;
// Additional fields for ETF factor analysis
var _biz=d.business||{};var _fund=d.fundamental||{};
