console.log('[CDS-DATA] Enriched:','RSI='+d.rsi,'SMA50='+d.sma50,'SMA200='+d.sma200,'Vol='+d.volume,'AvgVol='+d.avg_volume,'Beta='+d.beta,'PE='+d.pe);
