d.probUndervalued=d.probUndervalued||(d.upside>10?70:d.upside>0?50:30);
d.sentiment_score=d.sentiment_score||0;
d.confluence=d.confluence||{score:50,alignment:'NEUTRAL'};
if(!d.levels)d.levels={};if(!d.business)d.business={};if(!d.moat)d.moat={};
if(!d.valuation)d.valuation={};if(!d.intrinsicValue)d.intrinsicValue={};if(!d.allocation)d.allocation={};
d.levels.buy=d.levels.buy||d.price;d.levels.entry=d.levels.entry||d.price;
