h+='<td style="padding:5px 8px;text-align:right"><span style="padding:2px 6px;border-radius:100px;background:'+rC+'15;color:'+rC+';font-weight:800;font-size:7px">'+t.signal+'</span></td>';
h+='<td style="padding:5px 8px;text-align:right;color:'+rC+';font-weight:700">'+t.direction+'</td>';
h+='<td style="padding:5px 8px;text-align:right;font-weight:700;color:var(--text);font-size:7px;max-width:80px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">'+t.strategy+'</td>';
h+='<td style="padding:5px 8px;text-align:right;font-family:var(--mono)">'+S+(t.price||0).toLocaleString()+'</td>';
