const prob=parseInt(t.probability)||80;
const pCol=prob>=90?'var(--green)':prob>=85?'#22d3ee':'var(--amber)';
allTrades.push({...t,_type:'INDEX',_rank:t.rank||i+1,_prob:prob,_inst:t.index+' '+(t.bias||t.direction||'')});
