async function loadGlobalTicker(){
var row=document.getElementById('tickerRow');
var nrow=document.getElementById('newsRow');
if(!row)return;

function _bld(idx){
var up=idx.change_pct>0;var flat=Math.abs(idx.change_pct)<0.01;
var cls=flat?'tfl':up?'tup':'tdn';var arrow=flat?'':up?'\u25B2':'\u25BC';
var isVix=(idx.name||'').indexOf('VIX')>=0;
var fmt=idx.name==='GSR'?idx.price.toFixed(1)+'x':isVix?idx.price.toFixed(1):(idx.price||0)>=1000?(idx.price||0).toLocaleString():idx.price.toFixed(2);
return '<span class="ti"><span style="font-size:11px">'+(idx.flag||'')+'</span><span class="tn">'+(idx.name||'')+'</span><span class="tp">'+fmt+'</span><span class="tc '+cls+'">'+arrow+(Math.abs(idx.change_pct)||0).toFixed(2)+'%</span></span>';
}

// Fetch from our API — it pulls real Yahoo Finance data server-side
var loaded=false;
try{
var r=await fetch('/api/global-ticker');var d=await r.json();
if(d.success&&d.indices&&d.indices.length>0){
var items=d.indices.map(_bld).join('');
row.innerHTML=items+items;
row.style.animation='tscroll 50s linear infinite';
var _gt=document.getElementById('gticker');if(_gt){_gt.style.display='';var _nav=document.querySelector('nav');var _gth=_gt.offsetHeight||48;if(_nav){_nav.style.top=_gth+'px';document.documentElement.style.setProperty('--ticker-h',_gth+'px');}}
loaded=true;
}
}catch(e){console.log('Ticker:',e)}

// If API failed, show connecting message + auto-retry every 30s
if(!loaded){
row.innerHTML='<span class="ti"><span style="font-size:11px">\u{1F1EE}\u{1F1F3}</span><span class="tn">NIFTY 50</span><span class="tp">—</span><span class="tc tfl">Loading</span></span><span class="ti"><span style="font-size:11px">\u{1F1EE}\u{1F1F3}</span><span class="tn">SENSEX</span><span class="tp">—</span><span class="tc tfl">Loading</span></span><span class="ti"><span style="font-size:11px">\u{1F1FA}\u{1F1F8}</span><span class="tn">S&P 500</span><span class="tp">—</span><span class="tc tfl">Loading</span></span><span class="ti"><span style="font-size:11px">\u{1F1FA}\u{1F1F8}</span><span class="tn">NASDAQ</span><span class="tp">—</span><span class="tc tfl">Loading</span></span><span class="ti"><span style="font-size:11px">\u{1F4B1}</span><span class="tn">USD/INR</span><span class="tp">—</span><span class="tc tfl">Loading</span></span><span class="ti"><span style="font-size:11px">\u{1F947}</span><span class="tn">GOLD</span><span class="tp">—</span><span class="tc tfl">Loading</span></span><span class="ti"><span style="font-size:11px">\u{1F6E2}</span><span class="tn">CRUDE</span><span class="tp">—</span><span class="tc tfl">Loading</span></span><span class="ti"><span style="font-size:11px">\u{1F631}</span><span class="tn">VIX</span><span class="tp">—</span><span class="tc tfl">Loading</span></span>';
row.style.animation='tscroll 25s linear infinite';
setTimeout(loadGlobalTicker,10000);
}

// News bar
if(!nrow)return;
try{
var nr=await fetch('/api/news-ticker');var nd=await nr.json();
if(nd.success&&nd.headlines&&nd.headlines.length>0){
var nh=nd.headlines.map(function(n){
var ic=n.sentiment==='positive'?'\u{1F7E2}':n.sentiment==='negative'?'\u{1F534}':'\u{1F7E1}';
return '<span class="ni">'+ic+' <strong>'+(n.source||'')+':</strong> '+(n.title||'')+'</span>';
}).join('');
nrow.innerHTML=nh+nh;
nrow.style.animation='tscroll 90s linear infinite';
}else{throw new Error('no news')}
}catch(e){
nrow.innerHTML='<span class="ni">\u{1F7E2} Markets open — live data loading momentarily</span><span class="ni">\u{1F4CA} Track Nifty, Sensex, S&P 500, Gold, Crude, VIX in real-time</span><span class="ni">\u{1F7E2} Markets open — live data loading momentarily</span><span class="ni">\u{1F4CA} Enter any stock above to get instant AI analysis</span>';
nrow.style.animation='tscroll 30s linear infinite';
if(!loaded)setTimeout(loadGlobalTicker,60000);
}
}

