var _intraSell=['RSI','MACD','EMA','ADX','VWAP','Bollinger','Delta','Bias','MTF','Confluence','GEX'].filter(function(_,i){return [_iRSI,_iMACD,_iEMA,_iADX,_iVWAP,_iBB,_iDelta,_iBias,_iMTF,_confScore>55?'BUY':'SKIP',_iGEX][i]==='SELL'||[_iRSI,_iMACD,_iEMA,_iADX,_iVWAP,_iBB,_iDelta,_iBias,_iMTF,_confScore>55?'BUY':'SKIP',_iGEX][i]==='SELL OPTIONS'});
