if(_volR2>1.2){_bullCount++;_indLabels.push('Vol ✅ '+_volR2.toFixed(1)+'x')}else if(_volR2<0.7){_bearCount++;_indLabels.push('Vol ❌ Low')}else{_indLabels.push('Vol — Normal')}
