if(Math.abs(_gapPct)>0.3){if(_gapPct>0){_bullCount++;_indLabels.push('Gap ✅ +'+_gapPct.toFixed(1)+'%')}else{_bearCount++;_indLabels.push('Gap ❌ '+_gapPct.toFixed(1)+'%')}}

var _vTotal=_bullCount+_bearCount;var _vPct=_vTotal>0?Math.round(_bullCount/_vTotal*100):50;
