h+='.verdict{text-align:center;padding:20px;border-radius:12px;margin:12px 0}';
h+='.bar-row{display:flex;align-items:center;gap:8px;margin:3px 0}.bar-label{width:100px;font-size:9px;font-weight:700}.bar-bg{flex:1;height:10px;background:#e5e7eb;border-radius:5px;overflow:hidden}.bar-fill{height:100%;border-radius:5px}';
