// ═══════════════════════════════════════════════════════════════
// EMAIL PERSISTENCE + TAB ACCESS CONTROL
// Email saved in localStorage — enter once, never asked again
// 2-hour idle → re-enter (but email field pre-filled)
// Tab visibility based on email role
// ═══════════════════════════════════════════════════════════════

(function(){
  var IDLE_TIMEOUT=2*60*60*1000; // 2 hours
  window._lastActivity=Date.now();
  ['click','keydown','touchstart','scroll'].forEach(function(e){
    document.addEventListener(e,function(){window._lastActivity=Date.now()},true);
  });
  
  // ═══ 1. RESTORE EMAIL FROM localStorage ═══
  function restoreEmail(){
    var saved='';
    try{saved=localStorage.getItem('celesys_email')||''}catch(e){}
    if(!saved)return;
    
    window._verifiedEmail=saved;
    var el=document.getElementById('email');
    if(el&&!(el.dataset.real||'').trim()){
      el.dataset.real=saved;
      var p=saved.split('@');
      el.value=p[0][0]+'***@'+p[1];
      el.type='text';
    }
    applyTabAccess(saved);
  }
  
  // ═══ 2. SAVE EMAIL whenever entered ═══
  function patchEmailSave(){
    var el=document.getElementById('email');
    if(!el||el._celesysPatched)return;
    el._celesysPatched=true;
    el.addEventListener('blur',function(){
      var email=(el.dataset.real||el.value||'').trim().toLowerCase();
      if(email&&email.includes('@')&&email.includes('.')){
        try{localStorage.setItem('celesys_email',email)}catch(e){}
        window._verifiedEmail=email;
        window._lastActivity=Date.now();
        applyTabAccess(email);
      }
    });
  }
  
  // ═══ 3. TAB ACCESS CONTROL ═══
  function applyTabAccess(email){
    email=(email||'').toLowerCase();
    
    // Define roles
    var FULL_ACCESS = window.CELESYS_TIERS.full_access; // r63.4: refer to centralized tier definition
    var TRADING_ACCESS=['tmp@cls.com']; // Overview + Trading + Tools
    var PDF_ACCESS=['vj@vnky.com']; // Everything + PDF
    
    var role='public'; // Default: Overview + Tools only
    if(PDF_ACCESS.indexOf(email)>=0)role='admin';
    else if(FULL_ACCESS.indexOf(email)>=0)role='full';
    else if(TRADING_ACCESS.indexOf(email)>=0)role='trading';
    
    window._userRole=role;
    window._isPdfUser=(role==='admin');
    window._isTradingOnly=(role==='trading');
    
    // Tab IDs and which roles can see them
    // Format: {selector, roles that CAN see it}
    var tabRules=[
      // Main top tabs (by ID)
      {sel:'#tabBtnResearch', roles:['admin','full']},           // Stock tab
      {sel:'#tabBtnMarkets', roles:['admin','full']},            // Markets tab
      {sel:'#tabBtnDecide', roles:['admin','full']},             // Decide tab
      {sel:'#tabBtnDream', roles:['admin','full']},              // Dream tab
      {sel:'#tabBtnTrading', roles:['admin','full','trading']},  // Trader tab
      // tabBtnOverview → everyone
      // tabBtnTools → everyone
      
      // Decision Engine mode buttons
      {sel:'#deModeInvestor', roles:['admin','full']},
      {sel:'#deModeOptions', roles:['admin','full']},
      {sel:'#deModeTrader', roles:['admin','full','trading']},
      
      // Sub-tabs within Stock (Valuation, Technical, Activity, Risk)
      {sel:'[onclick*="switchTabGroup(\'research\'"]', roles:['admin','full']},
      
      // PDF
      {sel:'#pdfExportBtn', roles:['admin']},
      
      // Pro Scan, Reports, PMS buttons
      {sel:'[onclick*="proScan"]', roles:['admin','full']},
      {sel:'[onclick*="reports"]', roles:['admin','full']},
      {sel:'[onclick*="pms"]', roles:['admin','full']},
    ];
    
    tabRules.forEach(function(rule){
      try{
        var els=document.querySelectorAll(rule.sel);
        els.forEach(function(el2){
          if(rule.roles.indexOf(role)>=0){
            el2.style.display='';
          }else{
            el2.style.display='none';
          }
        });
      }catch(e){}
    });
    
    console.log('[ACCESS] Email: '+email+' → Role: '+role);
    
    // For trading/public roles: also hide sub-sections inside reports
    if(role==='trading'||role==='public'){
      // Hide Stock sub-tabs when report loads
      var _hideRestrictedContent=function(){
        // Valuation, Technical, Activity, Risk sub-tabs
        document.querySelectorAll('[onclick*="valuation"],[onclick*="technical"],[onclick*="activity"],[onclick*="risk"]').forEach(function(el3){el3.style.display='none'});
        // Report sections that shouldn't be visible
        document.querySelectorAll('#researchSection,#decideSection,#dreamSection,.investor-only,.premium-only').forEach(function(el3){el3.style.display='none'});
      };
      _hideRestrictedContent();
      // Re-apply every 2 seconds (catches dynamically loaded content)
      if(window._restrictTimer)clearInterval(window._restrictTimer);
      window._restrictTimer=setInterval(_hideRestrictedContent,2000);
      setTimeout(function(){clearInterval(window._restrictTimer)},60000); // Stop after 1 min
    }
  }
  
  // ═══ 4. IDLE CHECK — 2 hours no activity → clear session ═══
  setInterval(function(){
    var email=(window._verifiedEmail||'').trim();
    if(!email)return;
    
    if(Date.now()-window._lastActivity>=IDLE_TIMEOUT){
      // Idle too long — clear session but keep email in field for easy re-entry
      window._verifiedEmail='';
      try{localStorage.removeItem('celesys_email')}catch(e){}
      
      // Stop timers
      if(window._quickRefreshTimer)clearInterval(window._quickRefreshTimer);
      if(window._liveScannerTimer)clearInterval(window._liveScannerTimer);
      if(window._tradingRefreshTimer)clearInterval(window._tradingRefreshTimer);
      
      // Show idle message in report area
      var rpt=document.getElementById('report');
      if(rpt)rpt.innerHTML='<div style="text-align:center;padding:40px"><div style="font-size:36px;margin-bottom:12px">\u{1F634}</div><div style="font-size:16px;font-weight:900;color:var(--text)">Session Paused</div><div style="font-size:11px;color:var(--text3);margin-top:8px">Inactive for 2 hours. Click Analyze or switch tabs to resume.</div></div>';
      
      console.log('[SESSION] Idle timeout — session paused');
    }
  },60000); // Check every minute
  
  // ═══ 5. RE-VALIDATE on tab focus ═══
  document.addEventListener('visibilitychange',function(){
    if(!document.hidden){
      var email=(window._verifiedEmail||'').trim();
      if(!email){
        // Try restore from localStorage
        restoreEmail();
      }
      if(email){
        window._lastActivity=Date.now(); // User is back — reset idle
      }
    }
  });
  
  // ═══ INIT ═══
  if(document.readyState==='loading'){
    document.addEventListener('DOMContentLoaded',function(){
      setTimeout(function(){restoreEmail();patchEmailSave()},500);
    });
  }else{
    setTimeout(function(){restoreEmail();patchEmailSave()},500);
  }
  
  // Re-apply access after checkTradesAccess runs
  var _origCTA=window.checkTradesAccess;
  if(typeof checkTradesAccess==='function'){
    // Patch to also apply tab access after it runs
    var _patchInterval=setInterval(function(){
      var email=(window._verifiedEmail||'').trim();
      if(email){
        applyTabAccess(email);
        // Save to localStorage
        try{localStorage.setItem('celesys_email',email)}catch(e){}
      }
    },3000); // Re-apply every 3 seconds for first 30 seconds
    setTimeout(function(){clearInterval(_patchInterval)},30000);
  }
  
})();



// ═══ TAB ACCESS: MutationObserver — fires once when report shows ═══
(function(){
  function applyTabRoles(){
    var email=(window._verifiedEmail||'').toLowerCase();
    if(!email)return;
    
    var isTradingUser=(['tmp@cls.com'].indexOf(email)>=0);
    var isFullUser = (window.hasTier(email, 'trades')); // r63.4: was inline literal [bbk,vj] which == trades tier
    var isAdmin=email==='vj@vnky.com';
    
    var tradingBtn=document.getElementById('tabBtnTrading');
    if(tradingBtn&&(isTradingUser||isFullUser)){
      tradingBtn.style.setProperty('display','inline-flex','important');
    }
    
    // Show Decide, Research, Markets, Dream tabs for full/admin users
    if(isFullUser){
      ['tabBtnResearch','tabBtnMarkets','tabBtnDecide','tabBtnDream'].forEach(function(id){
        var el=document.getElementById(id);
        if(el)el.style.setProperty('display','inline-flex','important');
      });
    }
    
    if(isTradingUser){
      ['tabBtnResearch','tabBtnMarkets','tabBtnDecide','tabBtnDream'].forEach(function(id){
        var el=document.getElementById(id);
        if(el)el.style.setProperty('display','none','important');
      });
    }
  }
  
  // Watch for report becoming visible
  var rpt=document.getElementById('report');
  if(rpt){
    var obs=new MutationObserver(function(mutations){
      if(rpt.classList.contains('show')){
        applyTabRoles();
      }
    });
    obs.observe(rpt,{attributes:true,attributeFilter:['class']});
  }
  
  // Also run once on page load in case report is already visible
  setTimeout(applyTabRoles,2000);
})();


// ═══════════════════════════════════════════════════════════════════
// r63.1: Deep DD Toolbar — PDF export, Print, Copy URL
// ═══════════════════════════════════════════════════════════════════
// Adds 3 icon buttons floating top-right of the DD report.
// Tooltips on hover. Keyboard accessible (aria-labels).

window._csInjectDDToolbar = function() {
  // Don't add toolbar twice
  if (document.getElementById('csDDToolbar')) return;

  // Only add if there's actual report content (not error or loading state)
  var el = document.getElementById('deResult');
  if (!el) return;
  // Heuristic: report exists if it has substantial content (>1000 chars HTML)
  if (el.innerHTML.length < 1000) return;
  // Don't add if currently in error state
  if (el.querySelector('.cs-error-block')) return;

  var bar = document.createElement('div');
  bar.id = 'csDDToolbar';
  bar.setAttribute('role', 'toolbar');
  bar.setAttribute('aria-label', 'Report actions');
  bar.style.cssText = 'position:sticky;top:12px;float:right;z-index:50;display:flex;gap:6px;background:#fff;border:1px solid #e2e8f0;border-radius:8px;padding:5px;box-shadow:0 2px 8px rgba(0,0,0,0.06);font-family:Inter,sans-serif;margin-bottom:10px;margin-right:8px';

  bar.innerHTML = '' +
    // PDF button
    '<button onclick="window._csExportPDF()" data-tooltip="Export full report as PDF" aria-label="Export as PDF" class="cs-tb-btn">' +
      '<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"/><polyline points="14 2 14 8 20 8"/><line x1="9" y1="13" x2="15" y2="13"/><line x1="9" y1="17" x2="15" y2="17"/></svg>' +
      '<span style="font-size:10px;font-weight:700;letter-spacing:0.4px">PDF</span>' +
    '</button>' +
    // Print button
    '<button onclick="window._csPrintReport()" data-tooltip="Print report (browser dialog)" aria-label="Print report" class="cs-tb-btn">' +
      '<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><polyline points="6 9 6 2 18 2 18 9"/><path d="M6 18H4a2 2 0 0 1-2-2v-5a2 2 0 0 1 2-2h16a2 2 0 0 1 2 2v5a2 2 0 0 1-2 2h-2"/><rect x="6" y="14" width="12" height="8"/></svg>' +
    '</button>' +
    // Copy URL button
    '<button onclick="window._csCopyReportURL(this)" data-tooltip="Copy shareable link" aria-label="Copy URL" class="cs-tb-btn">' +
      '<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M10 13a5 5 0 0 0 7.54.54l3-3a5 5 0 0 0-7.07-7.07l-1.72 1.71"/><path d="M14 11a5 5 0 0 0-7.54-.54l-3 3a5 5 0 0 0 7.07 7.07l1.71-1.71"/></svg>' +
    '</button>';

  // Insert toolbar at the TOP of deResult (sticky positioning makes it stay visible while scrolling)
  el.insertBefore(bar, el.firstChild);

  // Inject styles ONCE per session
  if (!document.getElementById('csTbStyles')) {
    var style = document.createElement('style');
    style.id = 'csTbStyles';
    style.textContent = '' +
      '.cs-tb-btn { display:inline-flex; align-items:center; gap:5px; padding:6px 10px; background:#fff; color:#475569; border:1px solid #e2e8f0; border-radius:6px; cursor:pointer; transition:all 120ms; position:relative; }' +
      '.cs-tb-btn:hover { background:#1A3A78; color:#fff; border-color:#1A3A78; }' +
      '.cs-tb-btn:active { transform:scale(0.96); }' +
      '.cs-tb-btn:focus-visible { outline:2px solid #1A3A78; outline-offset:2px; }' +
      // Tooltip via data-tooltip attribute
      '.cs-tb-btn[data-tooltip]::after { content:attr(data-tooltip); position:absolute; top:100%; right:0; margin-top:8px; padding:5px 9px; background:#0f172a; color:#fff; font-size:10px; font-weight:600; border-radius:4px; white-space:nowrap; opacity:0; pointer-events:none; transition:opacity 150ms; letter-spacing:0.2px; }' +
      '.cs-tb-btn[data-tooltip]:hover::after { opacity:1; }' +
      '.cs-tb-btn[data-tooltip]::before { content:""; position:absolute; top:100%; right:14px; margin-top:3px; border:5px solid transparent; border-bottom-color:#0f172a; opacity:0; pointer-events:none; transition:opacity 150ms; }' +
      '.cs-tb-btn[data-tooltip]:hover::before { opacity:1; }' +
      // Print-only styles for Print button workflow
      '@media print { #csDDToolbar { display:none !important; } body { background:#fff !important; } }' +
      // Loading state
      '.cs-tb-btn.is-loading { pointer-events:none; opacity:0.6; }' +
      '.cs-tb-btn.is-loading svg { animation:csTbSpin 0.7s linear infinite; }' +
      '@keyframes csTbSpin { to { transform:rotate(360deg); } }';
    document.head.appendChild(style);
  }
};


// ═══════════════════════════════════════════════════════════════════
// PDF EXPORT — uses jsPDF + html2canvas (loaded from CDN in index.html)
// ═══════════════════════════════════════════════════════════════════
window._csExportPDF = async function() {
  var btn = event && event.currentTarget;

  // Check libraries are loaded
  if (typeof window.jspdf === 'undefined' || typeof window.html2canvas === 'undefined') {
    alert('PDF library not loaded yet. Please wait a moment and try again.');
    return;
  }

  // Validate report exists
  var reportEl = document.getElementById('deResult');
  if (!reportEl || reportEl.innerHTML.length < 1000) {
    alert('No report to export. Generate a Deep DD report first.');
    return;
  }

  // Try to detect ticker symbol from report for filename
  var ticker = (window._ddLastSymbol || 'REPORT').toUpperCase();
  var dateStr = new Date().toISOString().slice(0, 10);
  var filename = 'Celesys_DD_' + ticker + '_' + dateStr + '.pdf';

  // Show loading state
  if (btn) {
    btn.classList.add('is-loading');
    var origHtml = btn.innerHTML;
    btn.innerHTML = '<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><circle cx="12" cy="12" r="10"/><path d="M12 6v6l4 2"/></svg><span style="font-size:10px;font-weight:700">…</span>';
  }

  try {
    // Hide toolbar from capture
    var tb = document.getElementById('csDDToolbar');
    var tbDisplay = tb ? tb.style.display : '';
    if (tb) tb.style.display = 'none';

    // Capture report as canvas (whole content, ignore CSS scaling for accuracy)
    var canvas = await window.html2canvas(reportEl, {
      scale: 1.5,                    // higher resolution
      useCORS: true,
      allowTaint: false,
      backgroundColor: '#ffffff',
      logging: false,
      windowWidth: reportEl.scrollWidth,
      windowHeight: reportEl.scrollHeight,
    });

    // Restore toolbar
    if (tb) tb.style.display = tbDisplay;

    var imgData = canvas.toDataURL('image/jpeg', 0.92);

    // Build PDF — A4 portrait, mm units
    var pdf = new window.jspdf.jsPDF({
      orientation: 'portrait',
      unit: 'mm',
      format: 'a4',
    });

    var pageW = pdf.internal.pageSize.getWidth();   // 210mm
    var pageH = pdf.internal.pageSize.getHeight();  // 297mm
    var margin = 12;
    var contentW = pageW - (margin * 2);            // 186mm

    // ─── Cover page ───────────────────────────────────────────────
    // Navy header band
    pdf.setFillColor(26, 58, 120);  // #1A3A78
    pdf.rect(0, 0, pageW, 32, 'F');

    pdf.setTextColor(255, 255, 255);
    pdf.setFont('helvetica', 'bold');
    pdf.setFontSize(22);
    pdf.text('CELESYS', margin, 14);
    pdf.setFontSize(10);
    pdf.setFont('helvetica', 'normal');
    pdf.text('INSTITUTIONAL DEEP DUE DILIGENCE', margin, 21);
    pdf.setFontSize(8);
    pdf.text('Generated ' + new Date().toLocaleString(), margin, 27);

    // Ticker block
    pdf.setTextColor(15, 23, 42);  // #0f172a
    pdf.setFont('helvetica', 'bold');
    pdf.setFontSize(48);
    pdf.text(ticker, margin, 60);

    // Subtitle
    pdf.setFontSize(11);
    pdf.setFont('helvetica', 'normal');
    pdf.setTextColor(100, 116, 139);  // #64748b
    pdf.text('Multi-factor synthesis · 16-section institutional report', margin, 68);

    // Description block
    pdf.setDrawColor(226, 232, 240);
    pdf.line(margin, 75, pageW - margin, 75);

    pdf.setFontSize(9);
    pdf.setTextColor(71, 85, 105);
    var bodyLines = [
      'This report contains the full Deep Due Diligence analysis for ' + ticker + ',',
      'generated by the Celesys institutional research engine. Sections include:',
      '',
      '  • Bottom Line verdict (multi-factor synthesis)',
      '  • Investment thesis with DCF valuation',
      '  • Financial health snapshot',
      '  • Sector context vs benchmark ETF',
      '  • Porter\'s Five Forces analysis',
      '  • SWOT framework',
      '  • Catalysts: earnings + analyst targets',
      '  • Risk matrix with red flags',
      '  • Insider activity (Form 4 filings)',
      '  • Institutional ownership (13F holders)',
      '  • Earnings history with surprise tracking',
      '  • Layman blocks for every metric',
    ];
    var lineY = 85;
    bodyLines.forEach(function(line) {
      pdf.text(line, margin, lineY);
      lineY += 4.5;
    });

    // Disclaimer block
    pdf.setFillColor(255, 251, 235);  // amber-50
    pdf.setDrawColor(253, 230, 138);  // amber-200
    pdf.roundedRect(margin, pageH - 50, contentW, 32, 2, 2, 'FD');
    pdf.setFontSize(8);
    pdf.setTextColor(120, 53, 15);  // amber-900
    pdf.setFont('helvetica', 'bold');
    pdf.text('Important disclaimer', margin + 4, pageH - 43);
    pdf.setFont('helvetica', 'normal');
    pdf.setFontSize(7.5);
    var disclaimerLines = [
      'This report is research output, not investment advice. All figures sourced from public financial',
      'data (Yahoo Finance, Finnhub, NSE) and may have lag or gaps. Past performance does not predict',
      'future returns. Always conduct your own due diligence before any trade. Celesys provides analytical',
      'frameworks; investment decisions remain solely your responsibility.',
    ];
    var disclaimerY = pageH - 36;
    disclaimerLines.forEach(function(line) {
      pdf.text(line, margin + 4, disclaimerY);
      disclaimerY += 3.5;
    });

    // Footer
    pdf.setFontSize(7);
    pdf.setTextColor(148, 163, 184);
    pdf.text('celesys.ai · v4.63.x · Page 1 of report', margin, pageH - 6);

    // ─── Report pages ─────────────────────────────────────────────
    pdf.addPage();

    // Calculate scaled image dimensions
    var imgW = contentW;
    var imgH = (canvas.height * imgW) / canvas.width;
    var availableH = pageH - (margin * 2) - 8;  // leave room for footer

    // If image fits on one page, just add it
    if (imgH <= availableH) {
      pdf.addImage(imgData, 'JPEG', margin, margin, imgW, imgH);
      pdf.setFontSize(7);
      pdf.setTextColor(148, 163, 184);
      pdf.text('celesys.ai · ' + ticker + ' DD · Page 2', margin, pageH - 6);
    } else {
      // Multi-page: slice the image
      var sliceCanvas = document.createElement('canvas');
      sliceCanvas.width = canvas.width;
      var sliceHeightPx = Math.floor((availableH * canvas.width) / contentW);
      sliceCanvas.height = sliceHeightPx;
      var sctx = sliceCanvas.getContext('2d');

      var totalSlices = Math.ceil(canvas.height / sliceHeightPx);
      for (var i = 0; i < totalSlices; i++) {
        if (i > 0) pdf.addPage();
        var srcY = i * sliceHeightPx;
        var srcH = Math.min(sliceHeightPx, canvas.height - srcY);

        sctx.fillStyle = '#ffffff';
        sctx.fillRect(0, 0, sliceCanvas.width, sliceCanvas.height);
        sctx.drawImage(canvas, 0, srcY, canvas.width, srcH, 0, 0, canvas.width, srcH);

        var slicedDataUrl = sliceCanvas.toDataURL('image/jpeg', 0.92);
        var renderedH = (srcH * contentW) / canvas.width;
        pdf.addImage(slicedDataUrl, 'JPEG', margin, margin, contentW, renderedH);

        // Footer on each page
        pdf.setFontSize(7);
        pdf.setTextColor(148, 163, 184);
        pdf.text(
          'celesys.ai · ' + ticker + ' DD · Page ' + (i + 2) + ' of ' + (totalSlices + 1),
          margin,
          pageH - 6
        );
      }
    }

    // Save
    pdf.save(filename);

    if (btn) {
      btn.classList.remove('is-loading');
      btn.innerHTML = origHtml;
    }
  } catch (e) {
    if (btn) {
      btn.classList.remove('is-loading');
      btn.innerHTML = origHtml || btn.innerHTML;
    }
    var tb2 = document.getElementById('csDDToolbar');
    if (tb2) tb2.style.display = '';
    console.error('PDF export failed:', e);
    alert('PDF export failed: ' + e.message + '\n\nTry refreshing the page or use Print instead.');
  }
};


// ═══════════════════════════════════════════════════════════════════
// PRINT — uses native browser print dialog
// ═══════════════════════════════════════════════════════════════════
window._csPrintReport = function() {
  var reportEl = document.getElementById('deResult');
  if (!reportEl || reportEl.innerHTML.length < 1000) {
    alert('No report to print. Generate a Deep DD report first.');
    return;
  }
  // CSS @media print rule in toolbar styles already hides the toolbar
  window.print();
};


// ═══════════════════════════════════════════════════════════════════
// COPY URL — copies current page URL with ticker hash for sharing
// ═══════════════════════════════════════════════════════════════════
window._csCopyReportURL = function(btn) {
  var ticker = (window._ddLastSymbol || '').toUpperCase();
  var url = window.location.origin + window.location.pathname + '#dd/' + ticker;

  // Try modern clipboard API first
  if (navigator.clipboard && navigator.clipboard.writeText) {
    navigator.clipboard.writeText(url).then(function() {
      _csTbFlashSuccess(btn, 'Copied!');
    }).catch(function() {
      _csTbFallbackCopy(url, btn);
    });
  } else {
    _csTbFallbackCopy(url, btn);
  }
};

function _csTbFallbackCopy(text, btn) {
  // Fallback for older browsers
  var ta = document.createElement('textarea');
  ta.value = text;
  ta.style.position = 'fixed';
  ta.style.opacity = '0';
  document.body.appendChild(ta);
  ta.select();
  try {
    document.execCommand('copy');
    _csTbFlashSuccess(btn, 'Copied!');
  } catch (e) {
    alert('Could not copy. URL is: ' + text);
  }
  document.body.removeChild(ta);
}

function _csTbFlashSuccess(btn, message) {
  if (!btn) return;
  var orig = btn.getAttribute('data-tooltip');
  btn.setAttribute('data-tooltip', message || 'Copied!');
  btn.style.background = '#059669';
  btn.style.color = '#fff';
  btn.style.borderColor = '#059669';
  setTimeout(function() {
    btn.setAttribute('data-tooltip', orig);
    btn.style.background = '';
    btn.style.color = '';
    btn.style.borderColor = '';
  }, 1400);
}


// ═══════════════════════════════════════════════════════════════════
// AUTO-INJECT: inject toolbar after DD report renders
// ═══════════════════════════════════════════════════════════════════
// We hook into both _renderReportLegacy and _renderReportShellAladdin paths
// by polling deResult for content changes. Lightweight, runs once per render.
(function() {
  var lastInnerHTML = '';
  var checkCount = 0;
  var pollHandle = null;

  function checkAndInject() {
    var el = document.getElementById('deResult');
    if (!el) return;
    if (el.innerHTML === lastInnerHTML) return;
    lastInnerHTML = el.innerHTML;
    // Wait one tick for DOM to settle
    setTimeout(function() {
      if (typeof window._csInjectDDToolbar === 'function') {
        window._csInjectDDToolbar();
      }
    }, 50);
  }

  // r63.9: Start polling — runs forever as backup if renderReport wrapper fails
  function startPolling() {
    if (pollHandle) return;
    pollHandle = setInterval(checkAndInject, 800);
    // No timeout — polls run for the lifetime of the page
  }

  // Hook into existing tab dispatcher — when user is on DD tab, start polling
  document.addEventListener('DOMContentLoaded', function() {
    startPolling();
  });
  if (document.readyState !== 'loading') {
    startPolling();
  }
})();



// ═══════════════════════════════════════════════════════════════════
// r63.6: Find Similar Stocks — modal + scanner UI
// ═══════════════════════════════════════════════════════════════════
// Adds a "🔍 Find Similar" button to the Deep DD report. When clicked,
// opens a modal that scans the universe and shows results bucketed by
// price tier with similarity scores and matching factors.

window._csFindSimilarOpen = function(refTicker, region) {
  if (!refTicker) {
    refTicker = (window._ddLastSymbol || '').toUpperCase();
  }
  if (!region) region = (window._ddLastRegion || 'US').toUpperCase();
  if (!refTicker) {
    alert('No reference ticker. Generate a Deep DD report first.');
    return;
  }

  // Remove any existing modal
  var existing = document.getElementById('csFindSimilarModal');
  if (existing) existing.remove();

  // Build modal shell
  var modal = document.createElement('div');
  modal.id = 'csFindSimilarModal';
  modal.style.cssText = 'position:fixed;inset:0;background:rgba(15,23,42,0.7);z-index:9999;display:flex;align-items:flex-start;justify-content:center;padding:40px 20px;overflow-y:auto;font-family:Inter,sans-serif;animation:csFsFadeIn 200ms ease';
  modal.innerHTML = '' +
    '<div style="background:#fff;border-radius:14px;max-width:980px;width:100%;box-shadow:0 20px 60px rgba(0,0,0,0.4);overflow:hidden">' +
      // Header
      '<div style="padding:20px 28px;background:linear-gradient(135deg,#0A1628,#1A3A78);color:#fff;display:flex;justify-content:space-between;align-items:center">' +
        '<div>' +
          '<div style="font-size:18px;font-weight:800;font-family:Sora,sans-serif">🔍 Find Similar Stocks</div>' +
          '<div style="font-size:11px;color:rgba(255,255,255,0.7);margin-top:3px">Reference: <strong>' + refTicker + '</strong> · Region: ' + region + ' · Scanning curated universe</div>' +
        '</div>' +
        '<button onclick="document.getElementById(\'csFindSimilarModal\').remove()" style="background:rgba(255,255,255,0.15);color:#fff;border:none;width:32px;height:32px;border-radius:8px;font-size:18px;cursor:pointer">✕</button>' +
      '</div>' +
      // Body
      '<div id="csFsBody" style="padding:24px 28px;min-height:200px">' +
        '<div id="csFsLoading" style="text-align:center;padding:40px 20px">' +
          '<div style="display:inline-block;width:36px;height:36px;border:3px solid #e2e8f0;border-top-color:#1A3A78;border-radius:50%;animation:csFsSpin 0.8s linear infinite"></div>' +
          '<div style="margin-top:14px;font-size:13px;color:#475569;font-weight:600">Computing reference profile…</div>' +
          '<div id="csFsStatus" style="margin-top:6px;font-size:11px;color:#94a3b8">Then scanning ' + (region === 'US' ? '~80' : '~110') + ' candidates. Cold scan: ~2-4 min. Warm cache: instant.</div>' +
          '<div id="csFsTimer" style="margin-top:8px;font-size:10px;color:#64748b;font-variant-numeric:tabular-nums">Elapsed: 0s</div>' +
        '</div>' +
      '</div>' +
      // Footer
      '<div style="padding:14px 28px;background:#f8fafc;border-top:1px solid #e2e8f0;font-size:10px;color:#64748b;display:flex;justify-content:space-between;align-items:center">' +
        '<span>Similarity = 40% verdict + 35% fundamentals + 25% risk/momentum</span>' +
        '<span id="csFsScanInfo"></span>' +
      '</div>' +
    '</div>';
  
  document.body.appendChild(modal);
  
  // Inject styles once
  if (!document.getElementById('csFsStyles')) {
    var style = document.createElement('style');
    style.id = 'csFsStyles';
    style.textContent =
      '@keyframes csFsSpin { to { transform: rotate(360deg); } }' +
      '@keyframes csFsFadeIn { from { opacity: 0; } to { opacity: 1; } }';
    document.head.appendChild(style);
  }
  
  // Start elapsed timer
  var t0 = Date.now();
  var timerHandle = setInterval(function() {
    var el = document.getElementById('csFsTimer');
    if (el) {
      var sec = Math.floor((Date.now() - t0) / 1000);
      el.textContent = 'Elapsed: ' + sec + 's' + (sec > 30 ? ' (cold cache scan, please wait)' : '');
    }
  }, 1000);
  
  // Get email from app state
  var email = (window._verifiedEmail || window._authedEmail || window.localStorage.getItem('email') || '').trim();
  
  // Fetch
  fetch('/api/find-similar-stocks?reference=' + encodeURIComponent(refTicker) + '&region=' + region + '&email=' + encodeURIComponent(email))
    .then(function(r) { return r.json(); })
    .then(function(data) {
      clearInterval(timerHandle);
      if (!data.success) {
        document.getElementById('csFsBody').innerHTML =
          '<div style="text-align:center;padding:40px;color:#dc2626">' +
            '<div style="font-size:18px;font-weight:700;margin-bottom:8px">⚠️ Could not complete scan</div>' +
            '<div style="font-size:12px;color:#475569">' + (data.error || 'Unknown error') + '</div>' +
          '</div>';
        return;
      }
      _csFsRender(data);
    })
    .catch(function(err) {
      clearInterval(timerHandle);
      document.getElementById('csFsBody').innerHTML =
        '<div style="text-align:center;padding:40px;color:#dc2626">' +
          '<div style="font-size:18px;font-weight:700;margin-bottom:8px">⚠️ Network error</div>' +
          '<div style="font-size:12px;color:#475569">' + err.message + '</div>' +
        '</div>';
    });
};

function _csFsRender(data) {
  var ref = data.reference || {};
  var buckets = data.buckets || {};
  var bucketOrder = ['penny', 'low', 'mid', 'high', 'ultra'];
  
  var html = '';
  
  // Reference summary
  html += '<div style="background:linear-gradient(135deg,#F0F4FF,#E0E7FF);border:1px solid #c7d2fe;border-radius:10px;padding:14px 18px;margin-bottom:18px">';
  html += '<div style="font-size:9px;color:#4338ca;font-weight:800;letter-spacing:1.2px;margin-bottom:4px">REFERENCE PROFILE</div>';
  html += '<div style="display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:12px">';
  html += '<div><span style="font-size:18px;font-weight:900;color:#1A3A78;font-family:Sora,sans-serif">' + ref.ticker + '</span>';
  if (ref.name && ref.name !== ref.ticker) html += ' <span style="font-size:11px;color:#64748b">' + _csEscape(ref.name) + '</span>';
  html += '</div>';
  html += '<div style="font-size:11px;color:#475569">';
  html += '<strong>' + ref.currency_symbol + (ref.price || 0).toFixed(2) + '</strong> · ';
  html += 'Score <strong>' + Math.round(ref.verdict_score) + '/100</strong> (' + (ref.verdict_label || '—') + ')';
  if (ref.sector) html += ' · ' + _csEscape(ref.sector);
  html += '</div>';
  html += '</div>';
  html += '</div>';
  
  // Bucket sections
  for (var i = 0; i < bucketOrder.length; i++) {
    var bkey = bucketOrder[i];
    var bucket = buckets[bkey];
    if (!bucket) continue;
    var results = bucket.results || [];
    
    html += '<div style="margin-bottom:18px">';
    html += '<div style="display:flex;justify-content:space-between;align-items:baseline;margin-bottom:8px;padding:0 4px">';
    html += '<div style="font-size:13px;font-weight:800;color:#0f172a;font-family:Sora,sans-serif">' + bucket.label + '</div>';
    html += '<div style="font-size:10px;color:#94a3b8;font-weight:600">' + (results.length === 0 ? 'No matches' : results.length + ' match' + (results.length === 1 ? '' : 'es')) + '</div>';
    html += '</div>';
    
    if (results.length === 0) {
      html += '<div style="background:#f8fafc;border:1px dashed #e2e8f0;border-radius:8px;padding:14px;text-align:center;font-size:11px;color:#94a3b8">No similar stocks in this price tier within scanned universe</div>';
    } else {
      html += '<div style="display:grid;grid-template-columns:1fr;gap:8px">';
      for (var j = 0; j < results.length; j++) {
        var r = results[j];
        var simColor = r.similarity >= 75 ? '#059669' : (r.similarity >= 60 ? '#0891b2' : '#64748b');
        html += '<div style="border:1px solid #e2e8f0;border-radius:8px;padding:12px 14px;background:#fff;display:flex;justify-content:space-between;align-items:center;gap:14px">';
        html += '<div style="flex:1;min-width:0">';
        html += '<div style="display:flex;align-items:center;gap:8px;margin-bottom:3px">';
        html += '<span style="font-size:13px;font-weight:800;color:#1A3A78;font-family:Sora,sans-serif">' + r.ticker + '</span>';
        html += '<span style="font-size:9px;color:#475569;background:#f1f5f9;padding:2px 6px;border-radius:4px;font-weight:600">' + r.currency_symbol + (r.price || 0).toFixed(2) + '</span>';
        html += '<span style="font-size:9px;color:#fff;background:#1A3A78;padding:2px 6px;border-radius:4px;font-weight:700">' + Math.round(r.verdict_score) + '/100</span>';
        if (r.sector) html += '<span style="font-size:9px;color:#94a3b8">' + _csEscape(r.sector) + '</span>';
        html += '</div>';
        if (r.matches && r.matches.length > 0) {
          html += '<div style="font-size:10px;color:#64748b">' + r.matches.map(_csEscape).join(' · ') + '</div>';
        }
        html += '</div>';
        html += '<div style="text-align:right">';
        html += '<div style="font-size:18px;font-weight:900;color:' + simColor + ';font-variant-numeric:tabular-nums">' + Math.round(r.similarity) + '</div>';
        html += '<div style="font-size:8px;color:#94a3b8;letter-spacing:1px">SIM</div>';
        html += '</div>';
        html += '</div>';
      }
      html += '</div>';
    }
    
    html += '</div>';
  }
  
  document.getElementById('csFsBody').innerHTML = html;
  
  var scanInfo = document.getElementById('csFsScanInfo');
  if (scanInfo) {
    scanInfo.textContent = 'Scanned ' + data.scanned + ' · ' + data.valid + ' valid · ' + data.elapsed_sec + 's' + (data._cached ? ' (cached)' : '');
  }
}

function _csEscape(s) {
  if (s == null) return '';
  return String(s).replace(/[&<>"']/g, function(c) {
    return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c];
  });
}


// Auto-inject "Find Similar" button into Deep DD toolbar
window._csInjectFindSimilarButton = function() {
  var bar = document.getElementById('csDDToolbar');
  if (!bar) return;
  if (bar.querySelector('[data-action="find-similar"]')) return;  // already injected
  
  var btn = document.createElement('button');
  btn.setAttribute('data-action', 'find-similar');
  btn.setAttribute('data-tooltip', 'Find similar stocks across price tiers');
  btn.setAttribute('aria-label', 'Find Similar Stocks');
  btn.className = 'cs-tb-btn';
  btn.innerHTML =
    '<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><circle cx="11" cy="11" r="8"/><line x1="21" y1="21" x2="16.65" y2="16.65"/></svg>' +
    '<span style="font-size:10px;font-weight:700;letter-spacing:0.4px">SIMILAR</span>';
  btn.onclick = function() { window._csFindSimilarOpen(); };
  
  // Insert as first button so it's prominent
  bar.insertBefore(btn, bar.firstChild);
};

// Hook into existing DD toolbar polling — runs after toolbar appears
(function() {
  // r63.9: removed 10-min timeout. Polling runs forever as backup if renderReport
  // wrapper fails to fire. Cost: trivial (one getElementById per second).
  setInterval(function() {
    if (document.getElementById('csDDToolbar')) {
      window._csInjectFindSimilarButton();
    }
  }, 1000);
})();



